-- ================================================================
-- RAI-TECH — Standards Library Seed Script v2
-- Supabase Studio → SQL Editor: http://127.0.0.1:54323
-- 15 categories · 72 standards
-- Codes are globally unique: ACC-01, APP-01, SEC-01 etc.
-- Safe to re-run: WHERE NOT EXISTS guards on both name and code
-- ================================================================

DO $$
DECLARE
  v_user_id uuid;
  v_cat_0 uuid;
  v_cat_1 uuid;
  v_cat_2 uuid;
  v_cat_3 uuid;
  v_cat_4 uuid;
  v_cat_5 uuid;
  v_cat_6 uuid;
  v_cat_7 uuid;
  v_cat_8 uuid;
  v_cat_9 uuid;
  v_cat_10 uuid;
  v_cat_11 uuid;
  v_cat_12 uuid;
  v_cat_13 uuid;
  v_cat_14 uuid;
BEGIN
  SELECT id INTO v_user_id FROM auth.users ORDER BY created_at LIMIT 1;
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'No users found — log into Pronghorn first, then re-run.';
  END IF;
  RAISE NOTICE 'Seeding as user: %', v_user_id;

  -- ── CATEGORIES ───────────────────────────────────────────────

  INSERT INTO standard_categories (id, name, description, short_description, long_description, icon, color, order_index, is_system, created_by)
  SELECT gen_random_uuid(), 'Accessibility', 'WCAG and accessibility compliance standards', 'WCAG and accessibility compliance standards', 'WCAG and accessibility compliance standards', 'Eye', '#7C3AED', 10, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standard_categories WHERE name = 'Accessibility');
  SELECT id INTO v_cat_0 FROM standard_categories WHERE name = 'Accessibility' LIMIT 1;
  INSERT INTO standard_categories (id, name, description, short_description, long_description, icon, color, order_index, is_system, created_by)
  SELECT gen_random_uuid(), 'Application Standards', 'Best practices for application development and architecture', 'Best practices for application development and architecture', 'Best practices for application development and architecture', 'Code2', '#2563EB', 20, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standard_categories WHERE name = 'Application Standards');
  SELECT id INTO v_cat_1 FROM standard_categories WHERE name = 'Application Standards' LIMIT 1;
  INSERT INTO standard_categories (id, name, description, short_description, long_description, icon, color, order_index, is_system, created_by)
  SELECT gen_random_uuid(), 'Cyber Security', 'Security standards and frameworks including OWASP, NIST, and ISO', 'Security standards and frameworks including OWASP, NIST, and ISO', 'Security standards and frameworks including OWASP, NIST, and ISO', 'Shield', '#DC2626', 30, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standard_categories WHERE name = 'Cyber Security');
  SELECT id INTO v_cat_2 FROM standard_categories WHERE name = 'Cyber Security' LIMIT 1;
  INSERT INTO standard_categories (id, name, description, short_description, long_description, icon, color, order_index, is_system, created_by)
  SELECT gen_random_uuid(), 'Data Privacy', 'GDPR, CCPA, PHIA, PIPEDA, and data protection requirements', 'GDPR, CCPA, PHIA, PIPEDA, and data protection requirements', 'GDPR, CCPA, PHIA, PIPEDA, and data protection requirements', 'Lock', '#0D9488', 40, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standard_categories WHERE name = 'Data Privacy');
  SELECT id INTO v_cat_3 FROM standard_categories WHERE name = 'Data Privacy' LIMIT 1;
  INSERT INTO standard_categories (id, name, description, short_description, long_description, icon, color, order_index, is_system, created_by)
  SELECT gen_random_uuid(), 'Performance', 'Performance benchmarks and optimization standards', 'Performance benchmarks and optimization standards', 'Performance benchmarks and optimization standards', 'Zap', '#D97706', 50, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standard_categories WHERE name = 'Performance');
  SELECT id INTO v_cat_4 FROM standard_categories WHERE name = 'Performance' LIMIT 1;
  INSERT INTO standard_categories (id, name, description, short_description, long_description, icon, color, order_index, is_system, created_by)
  SELECT gen_random_uuid(), 'Architecture', 'Software architecture patterns, principles, and decision frameworks', 'Software architecture patterns, principles, and decision frameworks', 'Software architecture patterns, principles, and decision frameworks', 'Layers', '#1B3A6B', 60, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standard_categories WHERE name = 'Architecture');
  SELECT id INTO v_cat_5 FROM standard_categories WHERE name = 'Architecture' LIMIT 1;
  INSERT INTO standard_categories (id, name, description, short_description, long_description, icon, color, order_index, is_system, created_by)
  SELECT gen_random_uuid(), 'Testing', 'Testing standards, coverage requirements, and test design principles', 'Testing standards, coverage requirements, and test design principles', 'Testing standards, coverage requirements, and test design principles', 'TestTube2', '#16A34A', 70, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standard_categories WHERE name = 'Testing');
  SELECT id INTO v_cat_6 FROM standard_categories WHERE name = 'Testing' LIMIT 1;
  INSERT INTO standard_categories (id, name, description, short_description, long_description, icon, color, order_index, is_system, created_by)
  SELECT gen_random_uuid(), 'Logging and Observability', 'Structured logging, metrics, tracing, and alerting standards', 'Structured logging, metrics, tracing, and alerting standards', 'Structured logging, metrics, tracing, and alerting standards', 'Activity', '#EA580C', 80, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standard_categories WHERE name = 'Logging and Observability');
  SELECT id INTO v_cat_7 FROM standard_categories WHERE name = 'Logging and Observability' LIMIT 1;
  INSERT INTO standard_categories (id, name, description, short_description, long_description, icon, color, order_index, is_system, created_by)
  SELECT gen_random_uuid(), 'Database', 'PostgreSQL and Supabase database design, migration, and operational standards', 'PostgreSQL and Supabase database design, migration, and operational standards', 'PostgreSQL and Supabase database design, migration, and operational standards', 'Database', '#7C3AED', 90, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standard_categories WHERE name = 'Database');
  SELECT id INTO v_cat_8 FROM standard_categories WHERE name = 'Database' LIMIT 1;
  INSERT INTO standard_categories (id, name, description, short_description, long_description, icon, color, order_index, is_system, created_by)
  SELECT gen_random_uuid(), 'DevOps and CI/CD', 'Azure DevOps pipelines, Docker, OpenShift, and deployment standards', 'Azure DevOps pipelines, Docker, OpenShift, and deployment standards', 'Azure DevOps pipelines, Docker, OpenShift, and deployment standards', 'GitBranch', '#1B3A6B', 100, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standard_categories WHERE name = 'DevOps and CI/CD');
  SELECT id INTO v_cat_9 FROM standard_categories WHERE name = 'DevOps and CI/CD' LIMIT 1;
  INSERT INTO standard_categories (id, name, description, short_description, long_description, icon, color, order_index, is_system, created_by)
  SELECT gen_random_uuid(), 'TypeScript and React', 'TypeScript, React, and frontend development standards', 'TypeScript, React, and frontend development standards', 'TypeScript, React, and frontend development standards', 'FileCode', '#2563EB', 110, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standard_categories WHERE name = 'TypeScript and React');
  SELECT id INTO v_cat_10 FROM standard_categories WHERE name = 'TypeScript and React' LIMIT 1;
  INSERT INTO standard_categories (id, name, description, short_description, long_description, icon, color, order_index, is_system, created_by)
  SELECT gen_random_uuid(), 'Python', 'Python development standards for AI/ML, data pipelines, and backend services', 'Python development standards for AI/ML, data pipelines, and backend services', 'Python development standards for AI/ML, data pipelines, and backend services', 'Terminal', '#16A34A', 120, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standard_categories WHERE name = 'Python');
  SELECT id INTO v_cat_11 FROM standard_categories WHERE name = 'Python' LIMIT 1;
  INSERT INTO standard_categories (id, name, description, short_description, long_description, icon, color, order_index, is_system, created_by)
  SELECT gen_random_uuid(), 'API Design', 'RESTful API, GraphQL, and Supabase edge function design standards', 'RESTful API, GraphQL, and Supabase edge function design standards', 'RESTful API, GraphQL, and Supabase edge function design standards', 'Globe', '#0D9488', 130, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standard_categories WHERE name = 'API Design');
  SELECT id INTO v_cat_12 FROM standard_categories WHERE name = 'API Design' LIMIT 1;
  INSERT INTO standard_categories (id, name, description, short_description, long_description, icon, color, order_index, is_system, created_by)
  SELECT gen_random_uuid(), 'AI and ML', 'AI/ML integration, prompt engineering, and responsible AI standards', 'AI/ML integration, prompt engineering, and responsible AI standards', 'AI/ML integration, prompt engineering, and responsible AI standards', 'Brain', '#EA580C', 140, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standard_categories WHERE name = 'AI and ML');
  SELECT id INTO v_cat_13 FROM standard_categories WHERE name = 'AI and ML' LIMIT 1;
  INSERT INTO standard_categories (id, name, description, short_description, long_description, icon, color, order_index, is_system, created_by)
  SELECT gen_random_uuid(), 'Supabase', 'Supabase-specific patterns, RLS, edge functions, and local development', 'Supabase-specific patterns, RLS, edge functions, and local development', 'Supabase-specific patterns, RLS, edge functions, and local development', 'Database', '#16A34A', 150, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standard_categories WHERE name = 'Supabase');
  SELECT id INTO v_cat_14 FROM standard_categories WHERE name = 'Supabase' LIMIT 1;

  -- ── STANDARDS ────────────────────────────────────────────────

  -- Accessibility (prefix: ACC)
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_0, 'ACC-01', 'WCAG 2.1 AA Minimum Compliance', 'All Rai-Tech client applications must meet WCAG 2.1 Level AA as the minimum accessibility standard.', 'All Rai-Tech client applications must meet WCAG 2.1 Level AA as the minimum accessibility standard.', 'All Rai-Tech client applications must meet WCAG 2.1 Level AA as the minimum accessibility standard. This is the legal baseline for Alberta government clients and best practice for all others. Level AAA is the target for healthcare and government applications. Key requirements: perceivable (text alternatives for non-text content, captions for video, sufficient colour contrast ratio of 4.5:1 for normal text), operable (all functionality keyboard accessible, no keyboard traps, skip navigation links, visible focus indicators), understandable (labels for all inputs, error identification with text descriptions, consistent navigation), robust (valid HTML, ARIA roles correct, name/role/value exposed to assistive technology).', 'All Rai-Tech client applications must meet WCAG 2.1 Level AA as the minimum accessibility standard. This is the legal baseline for Alberta government clients and best practice for all others. Level AAA is the target for healthcare and government applications. Key requirements: perceivable (text alternatives for non-text content, captions for video, sufficient colour contrast ratio of 4.5:1 for normal text), operable (all functionality keyboard accessible, no keyboard traps, skip navigation links, visible focus indicators), understandable (labels for all inputs, error identification with text descriptions, consistent navigation), robust (valid HTML, ARIA roles correct, name/role/value exposed to assistive technology).', 10, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'ACC-01');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_0, 'ACC-02', 'Colour Contrast Requirements', 'Minimum contrast ratios must be met for all text.', 'Minimum contrast ratios must be met for all text.', 'Minimum contrast ratios must be met for all text. Normal text (<18pt or <14pt bold): 4.5:1 ratio against background. Large text (≥18pt or ≥14pt bold): 3:1 ratio. UI components and graphical objects: 3:1 against adjacent colours. Never convey information using colour alone — always pair with text, pattern, or icon. Test with tools: Colour Contrast Analyser, axe DevTools, or WAVE. Rai-Tech brand primary #5C52F3 on white passes AA for large text only — use on dark backgrounds or pair with white text for small text.', 'Minimum contrast ratios must be met for all text. Normal text (<18pt or <14pt bold): 4.5:1 ratio against background. Large text (≥18pt or ≥14pt bold): 3:1 ratio. UI components and graphical objects: 3:1 against adjacent colours. Never convey information using colour alone — always pair with text, pattern, or icon. Test with tools: Colour Contrast Analyser, axe DevTools, or WAVE. Rai-Tech brand primary #5C52F3 on white passes AA for large text only — use on dark backgrounds or pair with white text for small text.', 20, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'ACC-02');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_0, 'ACC-03', 'Keyboard Navigation Requirements', 'All interactive elements must be reachable and operable via keyboard alone.', 'All interactive elements must be reachable and operable via keyboard alone.', 'All interactive elements must be reachable and operable via keyboard alone. Tab order must be logical and follow visual reading order. Focus must never be trapped (except modal dialogs where focus is intentionally contained). All modals, dropdowns, and custom widgets must implement correct ARIA keyboard patterns (arrow keys for menus, Escape to close). Visible focus indicator required — do not suppress outline with outline:none without providing an alternative. Skip-to-main-content link must be the first focusable element on every page.', 'All interactive elements must be reachable and operable via keyboard alone. Tab order must be logical and follow visual reading order. Focus must never be trapped (except modal dialogs where focus is intentionally contained). All modals, dropdowns, and custom widgets must implement correct ARIA keyboard patterns (arrow keys for menus, Escape to close). Visible focus indicator required — do not suppress outline with outline:none without providing an alternative. Skip-to-main-content link must be the first focusable element on every page.', 30, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'ACC-03');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_0, 'ACC-04', 'ARIA Implementation Standards', 'Use semantic HTML first — ARIA is a last resort, not a first choice.', 'Use semantic HTML first — ARIA is a last resort, not a first choice.', 'Use semantic HTML first — ARIA is a last resort, not a first choice. Never use ARIA to fix broken semantics; fix the HTML instead. Required ARIA patterns: all form inputs have associated labels (for/id or aria-labelledby), all icon-only buttons have aria-label, all loading states have aria-live="polite" or aria-busy="true", all modals have role="dialog" with aria-modal="true" and aria-labelledby pointing to the dialog title, all error messages have role="alert" or are referenced via aria-describedby on the input. Test with screen readers: NVDA+Firefox (Windows), VoiceOver+Safari (Mac/iOS).', 'Use semantic HTML first — ARIA is a last resort, not a first choice. Never use ARIA to fix broken semantics; fix the HTML instead. Required ARIA patterns: all form inputs have associated labels (for/id or aria-labelledby), all icon-only buttons have aria-label, all loading states have aria-live="polite" or aria-busy="true", all modals have role="dialog" with aria-modal="true" and aria-labelledby pointing to the dialog title, all error messages have role="alert" or are referenced via aria-describedby on the input. Test with screen readers: NVDA+Firefox (Windows), VoiceOver+Safari (Mac/iOS).', 40, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'ACC-04');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_0, 'ACC-05', 'Alberta Government Accessibility Requirements', 'All applications developed for or by Alberta government clients must comply with the Alberta Government Accessibility Policy and the Accessible Information and Communications Standard.', 'All applications developed for or by Alberta government clients must comply with the Alberta Government Accessibility Policy and the Accessible Information and Communications Standard.', 'All applications developed for or by Alberta government clients must comply with the Alberta Government Accessibility Policy and the Accessible Information and Communications Standard. This requires WCAG 2.1 AA compliance, accessibility testing with at least two assistive technologies, an accessibility conformance report (ACR/VPAT) for procured software, and a documented accessibility feedback mechanism. Public-facing Alberta government digital services must include an accessibility statement. Healthcare applications (AHS) have additional requirements under PHIA to ensure accessible health information access.', 'All applications developed for or by Alberta government clients must comply with the Alberta Government Accessibility Policy and the Accessible Information and Communications Standard. This requires WCAG 2.1 AA compliance, accessibility testing with at least two assistive technologies, an accessibility conformance report (ACR/VPAT) for procured software, and a documented accessibility feedback mechanism. Public-facing Alberta government digital services must include an accessibility statement. Healthcare applications (AHS) have additional requirements under PHIA to ensure accessible health information access.', 50, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'ACC-05');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_0, 'ACC-06', 'Accessible Form Design', 'Every form input must have a visible label — never use placeholder text as the sole label (it disappears on focus).', 'Every form input must have a visible label — never use placeholder text as the sole label (it disappears on focus).', 'Every form input must have a visible label — never use placeholder text as the sole label (it disappears on focus). Group related inputs with fieldset/legend. Required fields must be indicated with both a visual marker and text (not colour alone). Error messages must: appear adjacent to the input, describe the error in plain language, suggest how to fix it, and be announced to screen readers via aria-live or focus management. Multi-step forms must indicate current step and total steps. Date inputs must accept multiple formats or use a clearly labelled date picker with keyboard support.', 'Every form input must have a visible label — never use placeholder text as the sole label (it disappears on focus). Group related inputs with fieldset/legend. Required fields must be indicated with both a visual marker and text (not colour alone). Error messages must: appear adjacent to the input, describe the error in plain language, suggest how to fix it, and be announced to screen readers via aria-live or focus management. Multi-step forms must indicate current step and total steps. Date inputs must accept multiple formats or use a clearly labelled date picker with keyboard support.', 60, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'ACC-06');

  -- Application Standards (prefix: APP)
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_1, 'APP-01', 'Clean Architecture — Default Pattern', 'All new .NET applications at Rai-Tech use Clean Architecture as the default structural pattern.', 'All new .NET applications at Rai-Tech use Clean Architecture as the default structural pattern.', 'All new .NET applications at Rai-Tech use Clean Architecture as the default structural pattern. Four layers: Domain (entities, value objects, domain events, interfaces — no external dependencies), Application (use cases, commands/queries via MediatR, DTOs, validators — depends only on Domain), Infrastructure (EF Core, external APIs, file system, email — implements Domain interfaces), Presentation (ASP.NET Core controllers or Minimal API, Blazor components — depends on Application). Dependency rule: inner layers must never reference outer layers. Use dependency injection to wire implementations at the composition root. Projects: [AppName].Domain, [AppName].Application, [AppName].Infrastructure, [AppName].Web.', 'All new .NET applications at Rai-Tech use Clean Architecture as the default structural pattern. Four layers: Domain (entities, value objects, domain events, interfaces — no external dependencies), Application (use cases, commands/queries via MediatR, DTOs, validators — depends only on Domain), Infrastructure (EF Core, external APIs, file system, email — implements Domain interfaces), Presentation (ASP.NET Core controllers or Minimal API, Blazor components — depends on Application). Dependency rule: inner layers must never reference outer layers. Use dependency injection to wire implementations at the composition root. Projects: [AppName].Domain, [AppName].Application, [AppName].Infrastructure, [AppName].Web.', 10, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'APP-01');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_1, 'APP-02', 'C# Coding Conventions', 'Follow Microsoft C# coding conventions with these Rai-Tech-specific additions.', 'Follow Microsoft C# coding conventions with these Rai-Tech-specific additions.', 'Follow Microsoft C# coding conventions with these Rai-Tech-specific additions. Naming: PascalCase for classes, methods, properties, public fields, constants; camelCase for local variables and parameters; _camelCase for private fields; IPascalCase for interfaces; TPascalCase for type parameters. File organisation: one class per file, filename matches class name, namespace matches folder structure. Prefer primary constructors (.NET 8+) for simple classes. Use records for immutable DTOs. Use file-scoped namespaces. Enable nullable reference types (<Nullable>enable</Nullable>) — treat all nullable warnings as errors in production code. Use var when the type is obvious from the right-hand side.', 'Follow Microsoft C# coding conventions with these Rai-Tech-specific additions. Naming: PascalCase for classes, methods, properties, public fields, constants; camelCase for local variables and parameters; _camelCase for private fields; IPascalCase for interfaces; TPascalCase for type parameters. File organisation: one class per file, filename matches class name, namespace matches folder structure. Prefer primary constructors (.NET 8+) for simple classes. Use records for immutable DTOs. Use file-scoped namespaces. Enable nullable reference types (<Nullable>enable</Nullable>) — treat all nullable warnings as errors in production code. Use var when the type is obvious from the right-hand side.', 20, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'APP-02');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_1, 'APP-03', 'Async/Await Patterns', 'All I/O operations must be async.', 'All I/O operations must be async.', 'All I/O operations must be async. Never use .Result, .Wait(), or GetAwaiter().GetResult() — these cause deadlocks in ASP.NET Core. Never use async void except for event handlers. Always propagate CancellationToken through async call chains — every public async method that does I/O must accept a CancellationToken parameter. Use ConfigureAwait(false) in library code but not in application code. Use Task.WhenAll for parallel async operations. Prefer IAsyncEnumerable<T> for streaming data. Name async methods with Async suffix. Use ValueTask<T> for hot paths where the result is often available synchronously.', 'All I/O operations must be async. Never use .Result, .Wait(), or GetAwaiter().GetResult() — these cause deadlocks in ASP.NET Core. Never use async void except for event handlers. Always propagate CancellationToken through async call chains — every public async method that does I/O must accept a CancellationToken parameter. Use ConfigureAwait(false) in library code but not in application code. Use Task.WhenAll for parallel async operations. Prefer IAsyncEnumerable<T> for streaming data. Name async methods with Async suffix. Use ValueTask<T> for hot paths where the result is often available synchronously.', 30, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'APP-03');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_1, 'APP-04', 'Dependency Injection Standards', 'Use constructor injection exclusively — no service locator, no static service providers, no IServiceProvider injected into business logic.', 'Use constructor injection exclusively — no service locator, no static service providers, no IServiceProvider injected into business logic.', 'Use constructor injection exclusively — no service locator, no static service providers, no IServiceProvider injected into business logic. Register services with the correct lifetime: Singleton for stateless services and shared caches, Scoped for EF Core DbContext and request-scoped services, Transient for lightweight stateless services. Never inject Scoped services into Singleton services (captive dependency bug). Use IOptions<T> for configuration injection, not IConfiguration directly. Register services in extension methods (AddMyFeature()) not inline in Program.cs. All service registrations must be in the Infrastructure or Web layer — never in Domain or Application.', 'Use constructor injection exclusively — no service locator, no static service providers, no IServiceProvider injected into business logic. Register services with the correct lifetime: Singleton for stateless services and shared caches, Scoped for EF Core DbContext and request-scoped services, Transient for lightweight stateless services. Never inject Scoped services into Singleton services (captive dependency bug). Use IOptions<T> for configuration injection, not IConfiguration directly. Register services in extension methods (AddMyFeature()) not inline in Program.cs. All service registrations must be in the Infrastructure or Web layer — never in Domain or Application.', 40, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'APP-04');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_1, 'APP-05', 'Result Pattern — Error Handling', 'Use the Result pattern for expected failures in the Application and Domain layers — never throw exceptions for expected business rule violations.', 'Use the Result pattern for expected failures in the Application and Domain layers — never throw exceptions for expected business rule violations.', 'Use the Result pattern for expected failures in the Application and Domain layers — never throw exceptions for expected business rule violations. Use FluentResults or a custom Result<T> type. Reserve exceptions for truly exceptional conditions (infrastructure failures, programming errors). Pattern: service methods return Result<T>, controllers unwrap and map to HTTP responses. Never catch-and-swallow exceptions. At the top level (controller/minimal API endpoint), use a global exception handler middleware that logs the exception and returns a structured ProblemDetails response (RFC 7807). Do not expose stack traces or internal error messages to clients.', 'Use the Result pattern for expected failures in the Application and Domain layers — never throw exceptions for expected business rule violations. Use FluentResults or a custom Result<T> type. Reserve exceptions for truly exceptional conditions (infrastructure failures, programming errors). Pattern: service methods return Result<T>, controllers unwrap and map to HTTP responses. Never catch-and-swallow exceptions. At the top level (controller/minimal API endpoint), use a global exception handler middleware that logs the exception and returns a structured ProblemDetails response (RFC 7807). Do not expose stack traces or internal error messages to clients.', 50, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'APP-05');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_1, 'APP-06', 'API Design Standards', 'REST API conventions for all Rai-Tech-built APIs.', 'REST API conventions for all Rai-Tech-built APIs.', 'REST API conventions for all Rai-Tech-built APIs. URL structure: lowercase kebab-case resources (/api/v1/patient-records), plural nouns for collections, nested for owned resources (/api/v1/patients/{id}/appointments). HTTP verbs: GET (read, idempotent), POST (create, non-idempotent), PUT (full replace), PATCH (partial update via JSON Patch), DELETE (remove). Status codes: 200 OK, 201 Created with Location header, 204 No Content, 400 Bad Request with validation errors, 401 Unauthorized, 403 Forbidden, 404 Not Found, 409 Conflict, 422 Unprocessable Entity, 500 Internal Server Error. Always version APIs in the URL (/api/v1/). Return ProblemDetails (RFC 7807) for all error responses. Pagination: use cursor-based for large datasets, offset for simple cases — always include total count.', 'REST API conventions for all Rai-Tech-built APIs. URL structure: lowercase kebab-case resources (/api/v1/patient-records), plural nouns for collections, nested for owned resources (/api/v1/patients/{id}/appointments). HTTP verbs: GET (read, idempotent), POST (create, non-idempotent), PUT (full replace), PATCH (partial update via JSON Patch), DELETE (remove). Status codes: 200 OK, 201 Created with Location header, 204 No Content, 400 Bad Request with validation errors, 401 Unauthorized, 403 Forbidden, 404 Not Found, 409 Conflict, 422 Unprocessable Entity, 500 Internal Server Error. Always version APIs in the URL (/api/v1/). Return ProblemDetails (RFC 7807) for all error responses. Pagination: use cursor-based for large datasets, offset for simple cases — always include total count.', 60, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'APP-06');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_1, 'APP-07', 'Entity Framework Core Standards', 'Use EF Core 8+ with code-first migrations.', 'Use EF Core 8+ with code-first migrations.', 'Use EF Core 8+ with code-first migrations. DbContext per bounded context — do not create a single God context. Use Fluent API for all configuration — not Data Annotations on domain entities (this would violate Clean Architecture by adding infrastructure concerns to the domain). Explicit column types for all money/decimal fields: HasColumnType("decimal(18,2)"). All string columns must have explicit max length. Use value converters for enums (store as string, not int). Enable query splitting for queries with multiple collection includes. Never use lazy loading in production — always explicit .Include() or projection. Use AsNoTracking() for read-only queries. All migrations must be reviewed before applying to production.', 'Use EF Core 8+ with code-first migrations. DbContext per bounded context — do not create a single God context. Use Fluent API for all configuration — not Data Annotations on domain entities (this would violate Clean Architecture by adding infrastructure concerns to the domain). Explicit column types for all money/decimal fields: HasColumnType("decimal(18,2)"). All string columns must have explicit max length. Use value converters for enums (store as string, not int). Enable query splitting for queries with multiple collection includes. Never use lazy loading in production — always explicit .Include() or projection. Use AsNoTracking() for read-only queries. All migrations must be reviewed before applying to production.', 70, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'APP-07');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_1, 'APP-08', 'Minimal API vs MVC Controllers', 'Default to Minimal API for new ASP.NET Core projects (simpler, less ceremony, better performance).', 'Default to Minimal API for new ASP.NET Core projects (simpler, less ceremony, better performance).', 'Default to Minimal API for new ASP.NET Core projects (simpler, less ceremony, better performance). Use MVC Controllers when: the endpoint group has complex authorization logic requiring action filters, you need output caching with VaryByQuery, the team is more familiar with MVC, or you''re maintaining an existing MVC codebase. Minimal API organisation: group endpoints by feature in extension methods (app.MapPatientEndpoints()), not in a single flat Program.cs. Use IEndpointFilter for cross-cutting concerns (validation, auth checks). Never mix Minimal API and MVC in the same project.', 'Default to Minimal API for new ASP.NET Core projects (simpler, less ceremony, better performance). Use MVC Controllers when: the endpoint group has complex authorization logic requiring action filters, you need output caching with VaryByQuery, the team is more familiar with MVC, or you''re maintaining an existing MVC codebase. Minimal API organisation: group endpoints by feature in extension methods (app.MapPatientEndpoints()), not in a single flat Program.cs. Use IEndpointFilter for cross-cutting concerns (validation, auth checks). Never mix Minimal API and MVC in the same project.', 80, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'APP-08');

  -- Cyber Security (prefix: SEC)
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_2, 'SEC-01', 'OWASP Top 10 — Required Mitigations', 'All Rai-Tech applications must address all 10 OWASP Top 10 risks.', 'All Rai-Tech applications must address all 10 OWASP Top 10 risks.', 'All Rai-Tech applications must address all 10 OWASP Top 10 risks. A01 Broken Access Control: implement least privilege, deny by default, test all access control logic. A02 Cryptographic Failures: TLS 1.2+ only, no MD5/SHA1, use bcrypt/Argon2 for passwords, encrypt sensitive data at rest. A03 Injection: parameterised queries everywhere, input validation at all boundaries, use ORMs correctly. A04 Insecure Design: threat model all new features, fail securely. A05 Security Misconfiguration: review all defaults, disable unnecessary features, use security headers. A06 Vulnerable Components: dependency scanning in CI, no components with known critical CVEs. A07 Auth Failures: MFA for all admin functions, secure session management, account lockout. A08 Software Integrity: verify downloads, use trusted package sources. A09 Logging Failures: log all auth events, access denials, and input validation failures. A10 SSRF: validate and restrict all server-side URL fetches.', 'All Rai-Tech applications must address all 10 OWASP Top 10 risks. A01 Broken Access Control: implement least privilege, deny by default, test all access control logic. A02 Cryptographic Failures: TLS 1.2+ only, no MD5/SHA1, use bcrypt/Argon2 for passwords, encrypt sensitive data at rest. A03 Injection: parameterised queries everywhere, input validation at all boundaries, use ORMs correctly. A04 Insecure Design: threat model all new features, fail securely. A05 Security Misconfiguration: review all defaults, disable unnecessary features, use security headers. A06 Vulnerable Components: dependency scanning in CI, no components with known critical CVEs. A07 Auth Failures: MFA for all admin functions, secure session management, account lockout. A08 Software Integrity: verify downloads, use trusted package sources. A09 Logging Failures: log all auth events, access denials, and input validation failures. A10 SSRF: validate and restrict all server-side URL fetches.', 10, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'SEC-01');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_2, 'SEC-02', 'Authentication — Azure AD / Microsoft Identity', 'All internal Rai-Tech and client applications must use Azure AD (Entra ID) for authentication via MSAL.NET.', 'All internal Rai-Tech and client applications must use Azure AD (Entra ID) for authentication via MSAL.NET.', 'All internal Rai-Tech and client applications must use Azure AD (Entra ID) for authentication via MSAL.NET. Never implement custom username/password authentication for production systems. Configuration: use OIDC/OAuth 2.0 authorization code flow with PKCE for web apps, client credentials flow for service-to-service. Token validation: validate issuer, audience, expiry on every request — use Microsoft.Identity.Web for ASP.NET Core. Never store tokens in localStorage (XSS vulnerable) — use httpOnly cookies or in-memory for SPAs. Require MFA for all admin roles via Azure AD Conditional Access. Token lifetime: access tokens max 1 hour, refresh tokens honour Azure AD policy.', 'All internal Rai-Tech and client applications must use Azure AD (Entra ID) for authentication via MSAL.NET. Never implement custom username/password authentication for production systems. Configuration: use OIDC/OAuth 2.0 authorization code flow with PKCE for web apps, client credentials flow for service-to-service. Token validation: validate issuer, audience, expiry on every request — use Microsoft.Identity.Web for ASP.NET Core. Never store tokens in localStorage (XSS vulnerable) — use httpOnly cookies or in-memory for SPAs. Require MFA for all admin roles via Azure AD Conditional Access. Token lifetime: access tokens max 1 hour, refresh tokens honour Azure AD policy.', 20, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'SEC-02');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_2, 'SEC-03', 'Secret Management', 'Secrets must never appear in source code, appsettings.json, or .env files committed to source control.', 'Secrets must never appear in source code, appsettings.json, or .env files committed to source control.', 'Secrets must never appear in source code, appsettings.json, or .env files committed to source control. Local development: use dotnet user-secrets or environment variables. CI/CD: use Azure DevOps variable groups (secret type). Production: use Azure Key Vault with managed identity — no connection strings or API keys in app configuration files. Rotate secrets on a schedule: API keys every 90 days, database passwords every 180 days, immediately on suspected compromise. Use separate Key Vaults per environment (dev/staging/prod). Audit Key Vault access via Azure Monitor. For Supabase projects: service_role key stored only in Key Vault and injected via environment variable — never in client-side code.', 'Secrets must never appear in source code, appsettings.json, or .env files committed to source control. Local development: use dotnet user-secrets or environment variables. CI/CD: use Azure DevOps variable groups (secret type). Production: use Azure Key Vault with managed identity — no connection strings or API keys in app configuration files. Rotate secrets on a schedule: API keys every 90 days, database passwords every 180 days, immediately on suspected compromise. Use separate Key Vaults per environment (dev/staging/prod). Audit Key Vault access via Azure Monitor. For Supabase projects: service_role key stored only in Key Vault and injected via environment variable — never in client-side code.', 30, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'SEC-03');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_2, 'SEC-04', 'HTTP Security Headers', 'All Rai-Tech web applications must set these HTTP security headers.', 'All Rai-Tech web applications must set these HTTP security headers.', 'All Rai-Tech web applications must set these HTTP security headers. Strict-Transport-Security: max-age=31536000; includeSubDomains (HSTS — force HTTPS). Content-Security-Policy: define explicit allowed sources for scripts, styles, images, fonts — no unsafe-inline for scripts. X-Frame-Options: DENY (prevent clickjacking). X-Content-Type-Options: nosniff. Referrer-Policy: strict-origin-when-cross-origin. Permissions-Policy: disable unused browser features. For ASP.NET Core use NWebsec or configure manually in middleware. Test with securityheaders.com. Supabase edge functions must set CORS headers explicitly — never use wildcard (*) in production.', 'All Rai-Tech web applications must set these HTTP security headers. Strict-Transport-Security: max-age=31536000; includeSubDomains (HSTS — force HTTPS). Content-Security-Policy: define explicit allowed sources for scripts, styles, images, fonts — no unsafe-inline for scripts. X-Frame-Options: DENY (prevent clickjacking). X-Content-Type-Options: nosniff. Referrer-Policy: strict-origin-when-cross-origin. Permissions-Policy: disable unused browser features. For ASP.NET Core use NWebsec or configure manually in middleware. Test with securityheaders.com. Supabase edge functions must set CORS headers explicitly — never use wildcard (*) in production.', 40, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'SEC-04');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_2, 'SEC-05', 'Input Validation and Sanitisation', 'Validate all input at the application boundary — never trust client input.', 'Validate all input at the application boundary — never trust client input.', 'Validate all input at the application boundary — never trust client input. Validation strategy: whitelist (accept known good) over blacklist (reject known bad). For .NET: use FluentValidation in the Application layer for business rule validation, DataAnnotations for DTO shape validation, and model binding validation in controllers. For Supabase/PostgreSQL: use check constraints and domain types for database-level validation. Never construct SQL from user input — use parameterised queries always. For HTML output: encode all user-supplied content (HtmlEncoder.Default.Encode()) — never render raw HTML from user input. For file uploads: validate MIME type server-side (not just extension), scan for malware, store outside web root, use random filenames.', 'Validate all input at the application boundary — never trust client input. Validation strategy: whitelist (accept known good) over blacklist (reject known bad). For .NET: use FluentValidation in the Application layer for business rule validation, DataAnnotations for DTO shape validation, and model binding validation in controllers. For Supabase/PostgreSQL: use check constraints and domain types for database-level validation. Never construct SQL from user input — use parameterised queries always. For HTML output: encode all user-supplied content (HtmlEncoder.Default.Encode()) — never render raw HTML from user input. For file uploads: validate MIME type server-side (not just extension), scan for malware, store outside web root, use random filenames.', 50, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'SEC-05');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_2, 'SEC-06', 'Supabase Row Level Security (RLS)', 'RLS must be enabled on every table in every Supabase project — no exceptions.', 'RLS must be enabled on every table in every Supabase project — no exceptions.', 'RLS must be enabled on every table in every Supabase project — no exceptions. Never disable RLS to "fix" a query — fix the policy instead. Policy design: separate policies for SELECT, INSERT, UPDATE, DELETE operations. Use auth.uid() for user-scoped policies. Use auth.jwt() -> ''role'' for role-based policies. Service role bypasses RLS — only use service_role key in trusted server-side code (edge functions), never in client code. Anon key respects RLS — anon users can only access rows your policies explicitly allow. Test RLS by querying as the anon role in SQL editor. All policies must be documented with a comment explaining the intended access pattern.', 'RLS must be enabled on every table in every Supabase project — no exceptions. Never disable RLS to "fix" a query — fix the policy instead. Policy design: separate policies for SELECT, INSERT, UPDATE, DELETE operations. Use auth.uid() for user-scoped policies. Use auth.jwt() -> ''role'' for role-based policies. Service role bypasses RLS — only use service_role key in trusted server-side code (edge functions), never in client code. Anon key respects RLS — anon users can only access rows your policies explicitly allow. Test RLS by querying as the anon role in SQL editor. All policies must be documented with a comment explaining the intended access pattern.', 60, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'SEC-06');

  -- Data Privacy (prefix: PRV)
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_3, 'PRV-01', 'PHIA Compliance — Alberta Health Information Act', 'All applications that collect, use, disclose, or store health information for Alberta Health Services or other AHS-affiliated clients must comply with the Health Information Act (HIA), which incorporates PHIA principles.', 'All applications that collect, use, disclose, or store health information for Alberta Health Services or other AHS-affiliated clients must comply with the Health Information Act (HIA), which incorporates PHIA principles.', 'All applications that collect, use, disclose, or store health information for Alberta Health Services or other AHS-affiliated clients must comply with the Health Information Act (HIA), which incorporates PHIA principles. Key requirements: collect only the minimum health information necessary for the stated purpose, obtain consent before collecting individually identifiable health information except where HIA permits otherwise, store health information only in Canada (no US cloud storage without explicit consent and safeguards), audit all access to individually identifiable health information, implement technical safeguards (encryption at rest and in transit, access controls, audit logging), report breaches to the Office of the Information and Privacy Commissioner of Alberta within 72 hours. Contact AHS privacy office before starting any new health data project.', 'All applications that collect, use, disclose, or store health information for Alberta Health Services or other AHS-affiliated clients must comply with the Health Information Act (HIA), which incorporates PHIA principles. Key requirements: collect only the minimum health information necessary for the stated purpose, obtain consent before collecting individually identifiable health information except where HIA permits otherwise, store health information only in Canada (no US cloud storage without explicit consent and safeguards), audit all access to individually identifiable health information, implement technical safeguards (encryption at rest and in transit, access controls, audit logging), report breaches to the Office of the Information and Privacy Commissioner of Alberta within 72 hours. Contact AHS privacy office before starting any new health data project.', 10, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'PRV-01');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_3, 'PRV-02', 'PIPEDA Compliance — Personal Information Protection', 'All Rai-Tech client applications that handle personal information of Canadian residents in the course of commercial activity must comply with PIPEDA (Personal Information Protection and Electronic Documents Act).', 'All Rai-Tech client applications that handle personal information of Canadian residents in the course of commercial activity must comply with PIPEDA (Personal Information Protection and Electronic Documents Act).', 'All Rai-Tech client applications that handle personal information of Canadian residents in the course of commercial activity must comply with PIPEDA (Personal Information Protection and Electronic Documents Act). Ten fair information principles: accountability (designate a privacy officer), identifying purposes (state why data is collected before or at time of collection), consent (obtain meaningful consent), limiting collection (collect only what is necessary), limiting use/disclosure/retention (use data only for stated purpose), accuracy (keep data accurate), safeguards (protect with appropriate security), openness (make privacy practices available), individual access (allow individuals to access their information), challenging compliance (provide a complaint process).', 'All Rai-Tech client applications that handle personal information of Canadian residents in the course of commercial activity must comply with PIPEDA (Personal Information Protection and Electronic Documents Act). Ten fair information principles: accountability (designate a privacy officer), identifying purposes (state why data is collected before or at time of collection), consent (obtain meaningful consent), limiting collection (collect only what is necessary), limiting use/disclosure/retention (use data only for stated purpose), accuracy (keep data accurate), safeguards (protect with appropriate security), openness (make privacy practices available), individual access (allow individuals to access their information), challenging compliance (provide a complaint process).', 20, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'PRV-02');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_3, 'PRV-03', 'PII Classification and Handling', 'Classify all data before storing or processing.', 'Classify all data before storing or processing.', 'Classify all data before storing or processing. Tier 1 — Highly Sensitive (health information, SIN, financial account numbers, biometrics): encrypt at rest with AES-256, encrypt in transit with TLS 1.3, access requires explicit authorisation, full audit trail, no logging of values. Tier 2 — Sensitive (name+address+email combined, date of birth, IP addresses): encrypt at rest, TLS in transit, role-based access, audit significant operations. Tier 3 — Internal (employee names, general contact info): access restricted to authenticated users, no special encryption requirement beyond transport. Tier 4 — Public: no restrictions. Never log Tier 1 or Tier 2 data — mask or omit from all log outputs.', 'Classify all data before storing or processing. Tier 1 — Highly Sensitive (health information, SIN, financial account numbers, biometrics): encrypt at rest with AES-256, encrypt in transit with TLS 1.3, access requires explicit authorisation, full audit trail, no logging of values. Tier 2 — Sensitive (name+address+email combined, date of birth, IP addresses): encrypt at rest, TLS in transit, role-based access, audit significant operations. Tier 3 — Internal (employee names, general contact info): access restricted to authenticated users, no special encryption requirement beyond transport. Tier 4 — Public: no restrictions. Never log Tier 1 or Tier 2 data — mask or omit from all log outputs.', 30, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'PRV-03');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_3, 'PRV-04', 'Data Retention and Deletion', 'Define retention periods for all data classes before starting any project.', 'Define retention periods for all data classes before starting any project.', 'Define retention periods for all data classes before starting any project. Health information: follow AHS/HIA retention schedules (typically 10 years for adult records, age of majority + 10 years for minor records). Personal information: retain only as long as necessary for the stated purpose, then securely delete. Implement soft-delete with IsDeleted flag for operational data, hard delete on schedule via background job. Support right-to-erasure requests: document which data can be deleted vs which must be retained for legal/regulatory reasons. Database backups: establish backup retention policy aligned with data classification (health data backups must also be protected and eventually purged). Never retain test data containing real personal information.', 'Define retention periods for all data classes before starting any project. Health information: follow AHS/HIA retention schedules (typically 10 years for adult records, age of majority + 10 years for minor records). Personal information: retain only as long as necessary for the stated purpose, then securely delete. Implement soft-delete with IsDeleted flag for operational data, hard delete on schedule via background job. Support right-to-erasure requests: document which data can be deleted vs which must be retained for legal/regulatory reasons. Database backups: establish backup retention policy aligned with data classification (health data backups must also be protected and eventually purged). Never retain test data containing real personal information.', 40, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'PRV-04');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_3, 'PRV-05', 'Audit Logging for Privacy', 'All access to personally identifiable information and health information must generate an audit log entry.', 'All access to personally identifiable information and health information must generate an audit log entry.', 'All access to personally identifiable information and health information must generate an audit log entry. Audit record must contain: timestamp (UTC), actor identity (user ID, system account), action (read, create, update, delete), resource identifier (record ID, table name), source IP, result (success/failure), and a reason/justification for health information access. Audit logs must be: immutable (no update/delete), stored separately from application logs, retained for minimum 7 years for health information, accessible for privacy investigations. Implement using PostgreSQL audit triggers or application-level audit middleware. Never log the actual data values — log only that access occurred to record ID X.', 'All access to personally identifiable information and health information must generate an audit log entry. Audit record must contain: timestamp (UTC), actor identity (user ID, system account), action (read, create, update, delete), resource identifier (record ID, table name), source IP, result (success/failure), and a reason/justification for health information access. Audit logs must be: immutable (no update/delete), stored separately from application logs, retained for minimum 7 years for health information, accessible for privacy investigations. Implement using PostgreSQL audit triggers or application-level audit middleware. Never log the actual data values — log only that access occurred to record ID X.', 50, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'PRV-05');

  -- Performance (prefix: PER)
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_4, 'PER-01', 'API Response Time Targets', 'Define and enforce response time budgets for all API endpoints.', 'Define and enforce response time budgets for all API endpoints.', 'Define and enforce response time budgets for all API endpoints. Interactive endpoints (user-initiated): p50 < 100ms, p95 < 200ms, p99 < 500ms. Background/batch operations: p95 < 5s with progress feedback. File uploads: progress indicator required for anything > 1MB. Database queries: no query should exceed 100ms on expected data volumes — use EXPLAIN ANALYZE to verify. Long-running operations: return 202 Accepted immediately with a job ID, provide a polling endpoint or webhook. Measure with realistic data volumes — do not test with empty databases. Add performance regression tests to CI for critical paths.', 'Define and enforce response time budgets for all API endpoints. Interactive endpoints (user-initiated): p50 < 100ms, p95 < 200ms, p99 < 500ms. Background/batch operations: p95 < 5s with progress feedback. File uploads: progress indicator required for anything > 1MB. Database queries: no query should exceed 100ms on expected data volumes — use EXPLAIN ANALYZE to verify. Long-running operations: return 202 Accepted immediately with a job ID, provide a polling endpoint or webhook. Measure with realistic data volumes — do not test with empty databases. Add performance regression tests to CI for critical paths.', 10, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'PER-01');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_4, 'PER-02', 'PostgreSQL Query Optimisation', 'All queries on tables with expected row counts > 10,000 must have appropriate indexes.', 'All queries on tables with expected row counts > 10,000 must have appropriate indexes.', 'All queries on tables with expected row counts > 10,000 must have appropriate indexes. Required indexes: all foreign key columns (PostgreSQL does not auto-index FKs unlike MySQL), all columns used in WHERE clauses with high selectivity, composite indexes for multi-column filters (column order matters — most selective first). Use EXPLAIN ANALYZE before and after adding indexes. Avoid N+1 queries — use JOINs or subqueries. Use CTEs for complex queries but be aware CTEs are optimisation fences in older PostgreSQL. Use partial indexes for filtered queries (WHERE is_deleted = false). Use covering indexes (INCLUDE) to avoid heap fetches for hot read paths. Monitor slow queries with pg_stat_statements.', 'All queries on tables with expected row counts > 10,000 must have appropriate indexes. Required indexes: all foreign key columns (PostgreSQL does not auto-index FKs unlike MySQL), all columns used in WHERE clauses with high selectivity, composite indexes for multi-column filters (column order matters — most selective first). Use EXPLAIN ANALYZE before and after adding indexes. Avoid N+1 queries — use JOINs or subqueries. Use CTEs for complex queries but be aware CTEs are optimisation fences in older PostgreSQL. Use partial indexes for filtered queries (WHERE is_deleted = false). Use covering indexes (INCLUDE) to avoid heap fetches for hot read paths. Monitor slow queries with pg_stat_statements.', 20, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'PER-02');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_4, 'PER-03', 'Caching Strategy', 'Define a caching strategy for every data access pattern.', 'Define a caching strategy for every data access pattern.', 'Define a caching strategy for every data access pattern. In-memory cache (IMemoryCache/.NET): reference data that changes rarely (lookup tables, config) — TTL 5-60 minutes, invalidate on write. Distributed cache (Redis): session data, rate limit counters, computed results shared across instances — TTL based on business rules. Database query cache: use for expensive aggregate queries, invalidate on relevant table writes. HTTP caching: set Cache-Control headers for static resources (max-age=31536000 for content-hashed assets), no-cache for authenticated API responses unless explicitly safe. Supabase: use PostgREST response caching for public endpoints. Never cache: health information without audit trail, financial transaction data, anything that must be real-time.', 'Define a caching strategy for every data access pattern. In-memory cache (IMemoryCache/.NET): reference data that changes rarely (lookup tables, config) — TTL 5-60 minutes, invalidate on write. Distributed cache (Redis): session data, rate limit counters, computed results shared across instances — TTL based on business rules. Database query cache: use for expensive aggregate queries, invalidate on relevant table writes. HTTP caching: set Cache-Control headers for static resources (max-age=31536000 for content-hashed assets), no-cache for authenticated API responses unless explicitly safe. Supabase: use PostgREST response caching for public endpoints. Never cache: health information without audit trail, financial transaction data, anything that must be real-time.', 30, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'PER-03');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_4, 'PER-04', 'Frontend Performance Budgets', 'All Rai-Tech-built web applications must meet Core Web Vitals targets.', 'All Rai-Tech-built web applications must meet Core Web Vitals targets.', 'All Rai-Tech-built web applications must meet Core Web Vitals targets. Largest Contentful Paint (LCP): < 2.5s on 4G. Interaction to Next Paint (INP): < 200ms. Cumulative Layout Shift (CLS): < 0.1. First Contentful Paint (FCP): < 1.8s. Bundle size budget: initial JS bundle < 200KB gzipped, use code splitting for routes and heavy components (React.lazy + Suspense). Images: use next-gen formats (WebP, AVIF), explicit width/height attributes to prevent layout shift, lazy loading for below-fold images. Fonts: use font-display: swap, preload critical fonts, self-host to avoid third-party DNS lookup. Measure with Lighthouse, WebPageTest, and Chrome UX Report.', 'All Rai-Tech-built web applications must meet Core Web Vitals targets. Largest Contentful Paint (LCP): < 2.5s on 4G. Interaction to Next Paint (INP): < 200ms. Cumulative Layout Shift (CLS): < 0.1. First Contentful Paint (FCP): < 1.8s. Bundle size budget: initial JS bundle < 200KB gzipped, use code splitting for routes and heavy components (React.lazy + Suspense). Images: use next-gen formats (WebP, AVIF), explicit width/height attributes to prevent layout shift, lazy loading for below-fold images. Fonts: use font-display: swap, preload critical fonts, self-host to avoid third-party DNS lookup. Measure with Lighthouse, WebPageTest, and Chrome UX Report.', 40, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'PER-04');

  -- Architecture (prefix: ARC)
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_5, 'ARC-01', 'Architecture Decision Records (ADRs)', 'All significant architectural decisions must be documented as Architecture Decision Records (ADRs) in the project repository under /docs/decisions/.', 'All significant architectural decisions must be documented as Architecture Decision Records (ADRs) in the project repository under /docs/decisions/.', 'All significant architectural decisions must be documented as Architecture Decision Records (ADRs) in the project repository under /docs/decisions/. ADR format: title, date, status (proposed/accepted/deprecated/superseded), context (what situation requires a decision), decision (what was decided and why), consequences (what becomes easier or harder as a result). Use the MADR template. Significant decisions include: choice of framework or language, database technology selection, authentication approach, API design pattern, deployment strategy, third-party service integration. ADRs are immutable once accepted — supersede them with new ADRs rather than editing. Review ADRs during project onboarding.', 'All significant architectural decisions must be documented as Architecture Decision Records (ADRs) in the project repository under /docs/decisions/. ADR format: title, date, status (proposed/accepted/deprecated/superseded), context (what situation requires a decision), decision (what was decided and why), consequences (what becomes easier or harder as a result). Use the MADR template. Significant decisions include: choice of framework or language, database technology selection, authentication approach, API design pattern, deployment strategy, third-party service integration. ADRs are immutable once accepted — supersede them with new ADRs rather than editing. Review ADRs during project onboarding.', 10, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'ARC-01');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_5, 'ARC-02', 'Microservices vs Monolith Decision Criteria', 'Default to a well-structured modular monolith unless there is a clear, specific reason to use microservices.', 'Default to a well-structured modular monolith unless there is a clear, specific reason to use microservices.', 'Default to a well-structured modular monolith unless there is a clear, specific reason to use microservices. Use microservices when: independent scalability is required for specific components, teams are large enough to own separate services (≥6 developers per service), deployment independence is required (different release cadences), technology diversity is genuinely needed. Do not use microservices for: new projects with uncertain domain boundaries, small teams (< 5 developers total), projects where operational complexity outweighs the benefits. When starting with a monolith, structure it for extractability — use well-defined module boundaries, avoid shared mutable state between modules, use domain events for cross-module communication.', 'Default to a well-structured modular monolith unless there is a clear, specific reason to use microservices. Use microservices when: independent scalability is required for specific components, teams are large enough to own separate services (≥6 developers per service), deployment independence is required (different release cadences), technology diversity is genuinely needed. Do not use microservices for: new projects with uncertain domain boundaries, small teams (< 5 developers total), projects where operational complexity outweighs the benefits. When starting with a monolith, structure it for extractability — use well-defined module boundaries, avoid shared mutable state between modules, use domain events for cross-module communication.', 20, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'ARC-02');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_5, 'ARC-03', 'Domain-Driven Design for Healthcare', 'Apply DDD tactical patterns for healthcare and government client projects.', 'Apply DDD tactical patterns for healthcare and government client projects.', 'Apply DDD tactical patterns for healthcare and government client projects. Identify bounded contexts at project start: Patient, Appointment, Billing, Clinical, Auth are typically separate bounded contexts in healthcare. Each bounded context owns its data — no direct database joins across contexts, use integration events for cross-context communication. Ubiquitous language: use the domain expert''s terminology in code (not developer jargon). Aggregate roots: identify aggregate boundaries carefully in healthcare (a Patient aggregate might include demographics but not clinical records — those are a separate aggregate). Value objects for domain concepts: BloodType, PhoneNumber, HealthcareNumber are value objects (immutable, equality by value), not strings.', 'Apply DDD tactical patterns for healthcare and government client projects. Identify bounded contexts at project start: Patient, Appointment, Billing, Clinical, Auth are typically separate bounded contexts in healthcare. Each bounded context owns its data — no direct database joins across contexts, use integration events for cross-context communication. Ubiquitous language: use the domain expert''s terminology in code (not developer jargon). Aggregate roots: identify aggregate boundaries carefully in healthcare (a Patient aggregate might include demographics but not clinical records — those are a separate aggregate). Value objects for domain concepts: BloodType, PhoneNumber, HealthcareNumber are value objects (immutable, equality by value), not strings.', 30, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'ARC-03');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_5, 'ARC-04', 'Event-Driven Architecture Patterns', 'Use event-driven patterns when: decoupling between services is required, audit trail of all state changes is needed (healthcare), eventual consistency is acceptable, background processing is needed.', 'Use event-driven patterns when: decoupling between services is required, audit trail of all state changes is needed (healthcare), eventual consistency is acceptable, background processing is needed.', 'Use event-driven patterns when: decoupling between services is required, audit trail of all state changes is needed (healthcare), eventual consistency is acceptable, background processing is needed. Implementation options in Rai-Tech stack: MediatR domain events (in-process, synchronous), Supabase Realtime (Postgres changes → WebSocket subscribers), PostgreSQL LISTEN/NOTIFY (lightweight pub/sub), dedicated message broker (RabbitMQ/Azure Service Bus for cross-service). Event design: events are named in past tense (PatientAdmitted, AppointmentCancelled), events are immutable, events contain enough data for consumers to act without querying back. Store events in an outbox table to guarantee at-least-once delivery.', 'Use event-driven patterns when: decoupling between services is required, audit trail of all state changes is needed (healthcare), eventual consistency is acceptable, background processing is needed. Implementation options in Rai-Tech stack: MediatR domain events (in-process, synchronous), Supabase Realtime (Postgres changes → WebSocket subscribers), PostgreSQL LISTEN/NOTIFY (lightweight pub/sub), dedicated message broker (RabbitMQ/Azure Service Bus for cross-service). Event design: events are named in past tense (PatientAdmitted, AppointmentCancelled), events are immutable, events contain enough data for consumers to act without querying back. Store events in an outbox table to guarantee at-least-once delivery.', 40, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'ARC-04');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_5, 'ARC-05', 'Supabase Architecture Patterns', 'Architecture principles for Supabase-powered applications.', 'Architecture principles for Supabase-powered applications.', 'Architecture principles for Supabase-powered applications. Edge functions for: complex business logic, third-party API calls (keeping secrets server-side), operations requiring service_role access. Client-side Supabase calls for: simple CRUD with RLS, real-time subscriptions, auth flows. Never put sensitive logic in client code — always use edge functions for anything involving secrets or privileged operations. Database functions (SECURITY DEFINER) for: complex queries that need elevated permissions, operations that must be atomic. Separate schemas for: application data (public), internal/admin data (use a restricted schema). Use PostgreSQL views for: commonly joined queries, row-level computed columns, simplified RLS policies.', 'Architecture principles for Supabase-powered applications. Edge functions for: complex business logic, third-party API calls (keeping secrets server-side), operations requiring service_role access. Client-side Supabase calls for: simple CRUD with RLS, real-time subscriptions, auth flows. Never put sensitive logic in client code — always use edge functions for anything involving secrets or privileged operations. Database functions (SECURITY DEFINER) for: complex queries that need elevated permissions, operations that must be atomic. Separate schemas for: application data (public), internal/admin data (use a restricted schema). Use PostgreSQL views for: commonly joined queries, row-level computed columns, simplified RLS policies.', 50, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'ARC-05');

  -- Testing (prefix: TST)
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_6, 'TST-01', 'Test Coverage Requirements', 'Minimum test coverage targets by layer.', 'Minimum test coverage targets by layer.', 'Minimum test coverage targets by layer. Domain layer: 90% line coverage — business rules must be thoroughly tested. Application layer (use cases/commands/queries): 80% line coverage. Infrastructure layer: integration tests for all repository methods and external service adapters — unit tests with mocks where integration tests are impractical. Presentation layer: component tests for complex UI logic, contract tests for API endpoints. Coverage is a floor not a goal — 80% coverage with meaningful tests is better than 95% coverage with trivial tests. Measure with dotnet-coverage or Coverlet. Fail CI if coverage drops below thresholds. Do not write tests purely to hit coverage numbers.', 'Minimum test coverage targets by layer. Domain layer: 90% line coverage — business rules must be thoroughly tested. Application layer (use cases/commands/queries): 80% line coverage. Infrastructure layer: integration tests for all repository methods and external service adapters — unit tests with mocks where integration tests are impractical. Presentation layer: component tests for complex UI logic, contract tests for API endpoints. Coverage is a floor not a goal — 80% coverage with meaningful tests is better than 95% coverage with trivial tests. Measure with dotnet-coverage or Coverlet. Fail CI if coverage drops below thresholds. Do not write tests purely to hit coverage numbers.', 10, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'TST-01');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_6, 'TST-02', 'Test Naming and Organisation', 'Test naming convention: MethodName_StateUnderTest_ExpectedBehavior.', 'Test naming convention: MethodName_StateUnderTest_ExpectedBehavior.', 'Test naming convention: MethodName_StateUnderTest_ExpectedBehavior. Examples: CalculateTotal_WithEmptyCart_ReturnsZero, ProcessPayment_WhenCardDeclined_ThrowsPaymentException, GetPatient_WithValidId_ReturnsPatientDto. Test organisation: mirror the production project structure, one test class per class under test, tests grouped by the method/scenario being tested. Test classes named [ClassUnderTest]Tests. Use descriptive test names — the test name should read as a specification. Arrange-Act-Assert (AAA) structure in every test with blank lines separating sections. One logical assertion per test — multiple Assert calls are fine if they test the same concept.', 'Test naming convention: MethodName_StateUnderTest_ExpectedBehavior. Examples: CalculateTotal_WithEmptyCart_ReturnsZero, ProcessPayment_WhenCardDeclined_ThrowsPaymentException, GetPatient_WithValidId_ReturnsPatientDto. Test organisation: mirror the production project structure, one test class per class under test, tests grouped by the method/scenario being tested. Test classes named [ClassUnderTest]Tests. Use descriptive test names — the test name should read as a specification. Arrange-Act-Assert (AAA) structure in every test with blank lines separating sections. One logical assertion per test — multiple Assert calls are fine if they test the same concept.', 20, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'TST-02');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_6, 'TST-03', '.NET Testing Stack', 'Standard testing stack for all Rai-Tech .NET projects.', 'Standard testing stack for all Rai-Tech .NET projects.', 'Standard testing stack for all Rai-Tech .NET projects. Test framework: xUnit (not MSTest or NUnit — xUnit is the modern standard with better async support). Mocking: Moq or NSubstitute — prefer NSubstitute for cleaner syntax. Assertions: FluentAssertions — provides readable failure messages and a rich assertion API (result.Should().Be(expected)). HTTP integration tests: WebApplicationFactory<Program> for in-process API testing. Database integration tests: use Testcontainers to spin up a real PostgreSQL instance per test run — no SQLite in-memory for integration tests (different SQL dialects cause false positives). Snapshot testing: Verify for complex object comparison. Performance tests: BenchmarkDotNet for performance-critical code paths.', 'Standard testing stack for all Rai-Tech .NET projects. Test framework: xUnit (not MSTest or NUnit — xUnit is the modern standard with better async support). Mocking: Moq or NSubstitute — prefer NSubstitute for cleaner syntax. Assertions: FluentAssertions — provides readable failure messages and a rich assertion API (result.Should().Be(expected)). HTTP integration tests: WebApplicationFactory<Program> for in-process API testing. Database integration tests: use Testcontainers to spin up a real PostgreSQL instance per test run — no SQLite in-memory for integration tests (different SQL dialects cause false positives). Snapshot testing: Verify for complex object comparison. Performance tests: BenchmarkDotNet for performance-critical code paths.', 30, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'TST-03');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_6, 'TST-04', 'Supabase and PostgreSQL Testing', 'Testing strategy for Supabase-backed applications.', 'Testing strategy for Supabase-backed applications.', 'Testing strategy for Supabase-backed applications. Local dev: always use supabase start for a local Supabase instance — never test against production or staging databases. RLS policy testing: write SQL tests that query as different roles (anon, authenticated with specific user IDs) to verify policies work correctly. Use pgTAP for database-level testing of functions, triggers, and RLS. Edge function testing: use Deno test with a local Supabase client pointing at local stack. Data setup: use database transactions in tests and roll back after each test to maintain clean state. Test realistic data volumes — seed with at least 10,000 rows for performance-sensitive query tests. CI: include supabase start and migration in CI pipeline before running tests.', 'Testing strategy for Supabase-backed applications. Local dev: always use supabase start for a local Supabase instance — never test against production or staging databases. RLS policy testing: write SQL tests that query as different roles (anon, authenticated with specific user IDs) to verify policies work correctly. Use pgTAP for database-level testing of functions, triggers, and RLS. Edge function testing: use Deno test with a local Supabase client pointing at local stack. Data setup: use database transactions in tests and roll back after each test to maintain clean state. Test realistic data volumes — seed with at least 10,000 rows for performance-sensitive query tests. CI: include supabase start and migration in CI pipeline before running tests.', 40, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'TST-04');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_6, 'TST-05', 'Integration and End-to-End Testing', 'Integration tests: test the full stack from API endpoint to database for all critical paths.', 'Integration tests: test the full stack from API endpoint to database for all critical paths.', 'Integration tests: test the full stack from API endpoint to database for all critical paths. Use real infrastructure (PostgreSQL via Testcontainers, real HTTP client) not mocks. End-to-end tests: use Playwright for browser automation — write E2E tests for critical user journeys only (login, primary workflow, checkout etc). E2E tests are slow and brittle — keep the suite small and focused. Accessibility testing: include axe-core accessibility checks in Playwright tests. API contract testing: use Pact for consumer-driven contract testing between services. Performance testing: k6 for load testing APIs — run weekly against staging, not just before go-live. Test environments: maintain separate test data sets, never use production data in tests.', 'Integration tests: test the full stack from API endpoint to database for all critical paths. Use real infrastructure (PostgreSQL via Testcontainers, real HTTP client) not mocks. End-to-end tests: use Playwright for browser automation — write E2E tests for critical user journeys only (login, primary workflow, checkout etc). E2E tests are slow and brittle — keep the suite small and focused. Accessibility testing: include axe-core accessibility checks in Playwright tests. API contract testing: use Pact for consumer-driven contract testing between services. Performance testing: k6 for load testing APIs — run weekly against staging, not just before go-live. Test environments: maintain separate test data sets, never use production data in tests.', 50, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'TST-05');

  -- Logging and Observability (prefix: OBS)
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_7, 'OBS-01', 'Structured Logging with Serilog', 'All .NET applications must use Serilog for structured logging.', 'All .NET applications must use Serilog for structured logging.', 'All .NET applications must use Serilog for structured logging. Never use string interpolation in log messages — this prevents log aggregation and search. Wrong: _logger.LogInformation($"Processing patient {patientId}"). Correct: _logger.LogInformation("Processing patient {PatientId}", patientId). Log sinks: local development → console (human-readable), production → Seq or Grafana Loki (structured JSON). Log levels: Verbose (detailed debugging, disabled in production), Debug (development debugging), Information (business events, user actions), Warning (unexpected but handled situations), Error (handled exceptions), Fatal (application cannot continue). Enable log level configuration via environment variable without rebuild. Enrich all logs with: MachineName, ThreadId, CorrelationId, Environment.', 'All .NET applications must use Serilog for structured logging. Never use string interpolation in log messages — this prevents log aggregation and search. Wrong: _logger.LogInformation($"Processing patient {patientId}"). Correct: _logger.LogInformation("Processing patient {PatientId}", patientId). Log sinks: local development → console (human-readable), production → Seq or Grafana Loki (structured JSON). Log levels: Verbose (detailed debugging, disabled in production), Debug (development debugging), Information (business events, user actions), Warning (unexpected but handled situations), Error (handled exceptions), Fatal (application cannot continue). Enable log level configuration via environment variable without rebuild. Enrich all logs with: MachineName, ThreadId, CorrelationId, Environment.', 10, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'OBS-01');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_7, 'OBS-02', 'Correlation IDs and Distributed Tracing', 'Every HTTP request must have a correlation ID that flows through the entire call chain.', 'Every HTTP request must have a correlation ID that flows through the entire call chain.', 'Every HTTP request must have a correlation ID that flows through the entire call chain. ASP.NET Core: generate CorrelationId in middleware if not present in request headers (X-Correlation-ID), add to response headers, add to all log entries via LogContext.PushProperty. For microservices: use OpenTelemetry with W3C TraceContext propagation (traceparent header). Trace all: incoming HTTP requests, outgoing HTTP calls, database queries (EF Core interceptors), queue message processing. Exporters: Jaeger or Zipkin for local dev, Azure Application Insights or Grafana Tempo for production. Minimum instrumentation: HTTP server, HTTP client, EF Core, and any custom business events.', 'Every HTTP request must have a correlation ID that flows through the entire call chain. ASP.NET Core: generate CorrelationId in middleware if not present in request headers (X-Correlation-ID), add to response headers, add to all log entries via LogContext.PushProperty. For microservices: use OpenTelemetry with W3C TraceContext propagation (traceparent header). Trace all: incoming HTTP requests, outgoing HTTP calls, database queries (EF Core interceptors), queue message processing. Exporters: Jaeger or Zipkin for local dev, Azure Application Insights or Grafana Tempo for production. Minimum instrumentation: HTTP server, HTTP client, EF Core, and any custom business events.', 20, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'OBS-02');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_7, 'OBS-03', 'Health Check Endpoints', 'Every service must expose health check endpoints.', 'Every service must expose health check endpoints.', 'Every service must expose health check endpoints. /health/live: liveness probe — returns 200 if the process is running (used by Kubernetes/OpenShift to know if it should restart the pod). Should only check if the application process is alive — not dependencies. /health/ready: readiness probe — returns 200 if the service can handle traffic (checks database connectivity, required external services, cache). /health: aggregate check for human consumption — include individual component health with latencies. For ASP.NET Core use Microsoft.Extensions.Diagnostics.HealthChecks. Include checks for: database connection, required external APIs, disk space (if writing files). Set readiness check to fail gracefully — return 503 when dependencies are down so load balancer routes traffic elsewhere.', 'Every service must expose health check endpoints. /health/live: liveness probe — returns 200 if the process is running (used by Kubernetes/OpenShift to know if it should restart the pod). Should only check if the application process is alive — not dependencies. /health/ready: readiness probe — returns 200 if the service can handle traffic (checks database connectivity, required external services, cache). /health: aggregate check for human consumption — include individual component health with latencies. For ASP.NET Core use Microsoft.Extensions.Diagnostics.HealthChecks. Include checks for: database connection, required external APIs, disk space (if writing files). Set readiness check to fail gracefully — return 503 when dependencies are down so load balancer routes traffic elsewhere.', 30, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'OBS-03');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_7, 'OBS-04', 'Metrics and Alerting', 'All production services must expose a Prometheus metrics endpoint at /metrics.', 'All production services must expose a Prometheus metrics endpoint at /metrics.', 'All production services must expose a Prometheus metrics endpoint at /metrics. Minimum metrics to instrument: HTTP request rate, error rate, and latency (histogram) per endpoint, database query duration, cache hit/miss ratio, queue depth and processing rate, business metrics (orders processed, patients registered etc). Use Prometheus.NET for .NET services. Grafana dashboards: create dashboards for each service covering the four golden signals (latency, traffic, errors, saturation). Alerts: page on > 5% error rate for 5 minutes, page on p95 latency > 500ms for 10 minutes, warn on > 80% CPU or memory for 15 minutes. For Supabase: enable built-in Supabase observability and connect to your Grafana instance.', 'All production services must expose a Prometheus metrics endpoint at /metrics. Minimum metrics to instrument: HTTP request rate, error rate, and latency (histogram) per endpoint, database query duration, cache hit/miss ratio, queue depth and processing rate, business metrics (orders processed, patients registered etc). Use Prometheus.NET for .NET services. Grafana dashboards: create dashboards for each service covering the four golden signals (latency, traffic, errors, saturation). Alerts: page on > 5% error rate for 5 minutes, page on p95 latency > 500ms for 10 minutes, warn on > 80% CPU or memory for 15 minutes. For Supabase: enable built-in Supabase observability and connect to your Grafana instance.', 40, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'OBS-04');

  -- Database (prefix: DB)
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_8, 'DB-01', 'PostgreSQL Schema Design Standards', 'All Rai-Tech projects use PostgreSQL as the primary database.', 'All Rai-Tech projects use PostgreSQL as the primary database.', 'All Rai-Tech projects use PostgreSQL as the primary database. Schema design rules: all table names lowercase_snake_case, column names lowercase_snake_case, no reserved words as column names. Required columns on every table: id (uuid default gen_random_uuid()), created_at (timestamptz default now()), updated_at (timestamptz default now()). Use a trigger to auto-update updated_at. Prefer UUIDs over serial integers for primary keys — avoids enumeration attacks and works better with distributed systems. Use text not varchar(n) for variable-length strings unless there is a specific length constraint to enforce. Use timestamptz not timestamp — always store times in UTC. Use check constraints to enforce valid states at the database level. Use enum types for finite sets of string values.', 'All Rai-Tech projects use PostgreSQL as the primary database. Schema design rules: all table names lowercase_snake_case, column names lowercase_snake_case, no reserved words as column names. Required columns on every table: id (uuid default gen_random_uuid()), created_at (timestamptz default now()), updated_at (timestamptz default now()). Use a trigger to auto-update updated_at. Prefer UUIDs over serial integers for primary keys — avoids enumeration attacks and works better with distributed systems. Use text not varchar(n) for variable-length strings unless there is a specific length constraint to enforce. Use timestamptz not timestamp — always store times in UTC. Use check constraints to enforce valid states at the database level. Use enum types for finite sets of string values.', 10, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'DB-01');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_8, 'DB-02', 'Migration Standards', 'All schema changes must go through migrations — never modify schema directly in production.', 'All schema changes must go through migrations — never modify schema directly in production.', 'All schema changes must go through migrations — never modify schema directly in production. Migration file naming: [timestamp]_[short_description].sql (Supabase CLI format). Each migration must be: idempotent where possible (use IF NOT EXISTS, IF EXISTS), forward-only (no rollback scripts — use a new migration to undo), tested locally with supabase db reset before committing. Destructive migrations (DROP TABLE, DROP COLUMN, truncate): require explicit approval from team lead, must have data backup confirmed before running. Column removal: mark deprecated, stop writing in one deploy, verify zero usage, then drop in a separate migration. Never rename columns or tables — add new, migrate data, remove old. Run migrations in CI before running tests.', 'All schema changes must go through migrations — never modify schema directly in production. Migration file naming: [timestamp]_[short_description].sql (Supabase CLI format). Each migration must be: idempotent where possible (use IF NOT EXISTS, IF EXISTS), forward-only (no rollback scripts — use a new migration to undo), tested locally with supabase db reset before committing. Destructive migrations (DROP TABLE, DROP COLUMN, truncate): require explicit approval from team lead, must have data backup confirmed before running. Column removal: mark deprecated, stop writing in one deploy, verify zero usage, then drop in a separate migration. Never rename columns or tables — add new, migrate data, remove old. Run migrations in CI before running tests.', 20, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'DB-02');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_8, 'DB-03', 'Soft Delete Pattern', 'Never hard delete records that have business or audit significance.', 'Never hard delete records that have business or audit significance.', 'Never hard delete records that have business or audit significance. Use soft delete: add deleted_at timestamptz column (null = active, timestamp = deleted), add deleted_by uuid column referencing auth.users. Create a view [table_name]_active that filters WHERE deleted_at IS NULL — application code queries the view, not the base table. Add a partial index on deleted_at for performance: CREATE INDEX idx_[table]_active ON [table] (id) WHERE deleted_at IS NULL. For health information: never delete — mark as superseded or archived per PHIA retention requirements. For Supabase: implement soft delete in RLS policies (policy filters on deleted_at IS NULL for normal users) and edge functions.', 'Never hard delete records that have business or audit significance. Use soft delete: add deleted_at timestamptz column (null = active, timestamp = deleted), add deleted_by uuid column referencing auth.users. Create a view [table_name]_active that filters WHERE deleted_at IS NULL — application code queries the view, not the base table. Add a partial index on deleted_at for performance: CREATE INDEX idx_[table]_active ON [table] (id) WHERE deleted_at IS NULL. For health information: never delete — mark as superseded or archived per PHIA retention requirements. For Supabase: implement soft delete in RLS policies (policy filters on deleted_at IS NULL for normal users) and edge functions.', 30, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'DB-03');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_8, 'DB-04', 'Supabase-Specific Database Patterns', 'Patterns specific to Supabase PostgreSQL.', 'Patterns specific to Supabase PostgreSQL.', 'Patterns specific to Supabase PostgreSQL. Always enable RLS before inserting any data — there is no safe order to add data then enable RLS. Use SECURITY DEFINER functions for operations that need elevated permissions — the function runs as the function owner, bypassing RLS for specific controlled operations. Use gen_random_uuid() for UUID generation — it is available without the uuid-ossp extension in modern PostgreSQL. Use auth.uid() in RLS policies to reference the currently authenticated user. Supabase storage: always use storage buckets with RLS policies, never make buckets public unless the content is truly public. Use Supabase Vault for encrypting sensitive column values (available as pgsodium extension). Realtime: only enable realtime on tables that need it — it adds overhead.', 'Patterns specific to Supabase PostgreSQL. Always enable RLS before inserting any data — there is no safe order to add data then enable RLS. Use SECURITY DEFINER functions for operations that need elevated permissions — the function runs as the function owner, bypassing RLS for specific controlled operations. Use gen_random_uuid() for UUID generation — it is available without the uuid-ossp extension in modern PostgreSQL. Use auth.uid() in RLS policies to reference the currently authenticated user. Supabase storage: always use storage buckets with RLS policies, never make buckets public unless the content is truly public. Use Supabase Vault for encrypting sensitive column values (available as pgsodium extension). Realtime: only enable realtime on tables that need it — it adds overhead.', 40, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'DB-04');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_8, 'DB-05', 'Database Connection Management', 'Connection strings must never be hardcoded or committed to source control.', 'Connection strings must never be hardcoded or committed to source control.', 'Connection strings must never be hardcoded or committed to source control. Local development: use dotnet user-secrets or Supabase CLI local stack connection string. Production: inject via environment variable from Azure Key Vault or Supabase Secrets. Connection pooling: use PgBouncer in transaction mode for applications with many short-lived connections (APIs). EF Core: configure connection pool size based on expected concurrency (default max pool size 100 is often too high for cloud instances — set to 20-50 for serverless). Supabase: use the connection pooler URL (port 6543) for serverless/edge functions, use the direct URL (port 5432) only for migrations and long-lived server processes. Set connection timeout to 30s and command timeout to 60s — never unlimited.', 'Connection strings must never be hardcoded or committed to source control. Local development: use dotnet user-secrets or Supabase CLI local stack connection string. Production: inject via environment variable from Azure Key Vault or Supabase Secrets. Connection pooling: use PgBouncer in transaction mode for applications with many short-lived connections (APIs). EF Core: configure connection pool size based on expected concurrency (default max pool size 100 is often too high for cloud instances — set to 20-50 for serverless). Supabase: use the connection pooler URL (port 6543) for serverless/edge functions, use the direct URL (port 5432) only for migrations and long-lived server processes. Set connection timeout to 30s and command timeout to 60s — never unlimited.', 50, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'DB-05');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_8, 'DB-06', 'pgvector Standards', 'Standards for vector similarity search using pgvector.', 'Standards for vector similarity search using pgvector.', 'Standards for vector similarity search using pgvector. Extension: CREATE EXTENSION IF NOT EXISTS vector. Dimension selection: OpenAI text-embedding-3-small = 1536 dimensions, text-embedding-3-large = 3072, Nemotron embeddings = match model output dimension. Column type: content_embedding vector(1536). Index type: use HNSW for production (better query performance than IVFFlat for most cases): CREATE INDEX ON [table] USING hnsw (embedding vector_cosine_ops). Similarity threshold: for semantic search, cosine similarity > 0.8 indicates high relevance — tune per use case. Hybrid search: combine pgvector similarity with PostgreSQL full-text search (tsvector/tsquery) using RRF (Reciprocal Rank Fusion) for better results than either alone. Always index the embedding column before querying tables > 10,000 rows.', 'Standards for vector similarity search using pgvector. Extension: CREATE EXTENSION IF NOT EXISTS vector. Dimension selection: OpenAI text-embedding-3-small = 1536 dimensions, text-embedding-3-large = 3072, Nemotron embeddings = match model output dimension. Column type: content_embedding vector(1536). Index type: use HNSW for production (better query performance than IVFFlat for most cases): CREATE INDEX ON [table] USING hnsw (embedding vector_cosine_ops). Similarity threshold: for semantic search, cosine similarity > 0.8 indicates high relevance — tune per use case. Hybrid search: combine pgvector similarity with PostgreSQL full-text search (tsvector/tsquery) using RRF (Reciprocal Rank Fusion) for better results than either alone. Always index the embedding column before querying tables > 10,000 rows.', 60, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'DB-06');

  -- DevOps and CI/CD (prefix: DEV)
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_9, 'DEV-01', 'Azure DevOps Pipeline Requirements', 'All Rai-Tech projects must have a CI/CD pipeline in Azure DevOps.', 'All Rai-Tech projects must have a CI/CD pipeline in Azure DevOps.', 'All Rai-Tech projects must have a CI/CD pipeline in Azure DevOps. Pipeline stages: Build (compile, lint, unit tests), Test (integration tests, Supabase migration test, coverage check), Security (dependency audit, SAST scan), Package (Docker image build and push), Deploy-Dev (automatic on merge to develop), Deploy-Staging (automatic on merge to main), Deploy-Prod (manual approval required). Branch triggers: feature/* → CI only, develop → CI + deploy dev, main → CI + deploy staging + approval-gated prod. Never deploy directly to production without staging validation. Pipeline as code: all pipelines defined in azure-pipelines.yml in the repository — never configure pipelines only through the UI.', 'All Rai-Tech projects must have a CI/CD pipeline in Azure DevOps. Pipeline stages: Build (compile, lint, unit tests), Test (integration tests, Supabase migration test, coverage check), Security (dependency audit, SAST scan), Package (Docker image build and push), Deploy-Dev (automatic on merge to develop), Deploy-Staging (automatic on merge to main), Deploy-Prod (manual approval required). Branch triggers: feature/* → CI only, develop → CI + deploy dev, main → CI + deploy staging + approval-gated prod. Never deploy directly to production without staging validation. Pipeline as code: all pipelines defined in azure-pipelines.yml in the repository — never configure pipelines only through the UI.', 10, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'DEV-01');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_9, 'DEV-02', 'Docker Image Standards', 'All Rai-Tech applications must be containerised with Docker.', 'All Rai-Tech applications must be containerised with Docker.', 'All Rai-Tech applications must be containerised with Docker. Base image: use official Microsoft images for .NET (mcr.microsoft.com/dotnet/aspnet:8.0 for runtime, mcr.microsoft.com/dotnet/sdk:8.0 for build), official Node.js images for TypeScript, official Python images. Never use :latest tag — always pin to a specific version. Multi-stage builds: separate build stage from runtime stage — runtime image must not contain SDK or build tools. Security: run as non-root user (USER app or create a dedicated user), read-only root filesystem where possible, no secrets in Dockerfile or image layers. Image size: keep runtime images < 200MB — use alpine variants where compatible. Health check: add HEALTHCHECK instruction to Dockerfile. Scan images with Trivy or Snyk in CI — fail on critical vulnerabilities.', 'All Rai-Tech applications must be containerised with Docker. Base image: use official Microsoft images for .NET (mcr.microsoft.com/dotnet/aspnet:8.0 for runtime, mcr.microsoft.com/dotnet/sdk:8.0 for build), official Node.js images for TypeScript, official Python images. Never use :latest tag — always pin to a specific version. Multi-stage builds: separate build stage from runtime stage — runtime image must not contain SDK or build tools. Security: run as non-root user (USER app or create a dedicated user), read-only root filesystem where possible, no secrets in Dockerfile or image layers. Image size: keep runtime images < 200MB — use alpine variants where compatible. Health check: add HEALTHCHECK instruction to Dockerfile. Scan images with Trivy or Snyk in CI — fail on critical vulnerabilities.', 20, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'DEV-02');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_9, 'DEV-03', 'Branch Strategy', 'Rai-Tech standard Git branching model.', 'Rai-Tech standard Git branching model.', 'Rai-Tech standard Git branching model. main: production-ready code, always deployable, protected branch. develop: integration branch, merges to main via PR. feature/[ticket-number]-[short-description]: feature development, branch from develop. bugfix/[ticket-number]-[short-description]: bug fixes, branch from develop. hotfix/[ticket-number]-[short-description]: critical production fixes, branch from main, merge to both main and develop. Release branches: optional, use release/[version] for release candidate stabilisation. Pull request requirements: minimum 1 reviewer approval (2 for main merges), all CI checks passing, no merge conflicts. Commit messages: use Conventional Commits format (feat:, fix:, docs:, chore:, refactor:, test:). Never force push to main or develop.', 'Rai-Tech standard Git branching model. main: production-ready code, always deployable, protected branch. develop: integration branch, merges to main via PR. feature/[ticket-number]-[short-description]: feature development, branch from develop. bugfix/[ticket-number]-[short-description]: bug fixes, branch from develop. hotfix/[ticket-number]-[short-description]: critical production fixes, branch from main, merge to both main and develop. Release branches: optional, use release/[version] for release candidate stabilisation. Pull request requirements: minimum 1 reviewer approval (2 for main merges), all CI checks passing, no merge conflicts. Commit messages: use Conventional Commits format (feat:, fix:, docs:, chore:, refactor:, test:). Never force push to main or develop.', 30, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'DEV-03');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_9, 'DEV-04', 'OpenShift Deployment Standards', 'Standards for deploying Rai-Tech applications to OpenShift (OCP).', 'Standards for deploying Rai-Tech applications to OpenShift (OCP).', 'Standards for deploying Rai-Tech applications to OpenShift (OCP). Deployment configuration: define resource requests and limits for all containers (CPU request: 100m, limit: 500m; Memory request: 128Mi, limit: 512Mi — adjust per workload). Liveness probe: use /health/live endpoint, initialDelaySeconds: 30, periodSeconds: 10. Readiness probe: use /health/ready endpoint, initialDelaySeconds: 15, periodSeconds: 5. Config maps for non-sensitive configuration, Secrets for sensitive values. Network policies: deny all ingress by default, explicitly allow required traffic. Image pull policy: Always for latest-based tags, IfNotPresent for pinned versions. Use OpenShift Routes with TLS termination — never expose unencrypted HTTP externally. Namespace per environment (dev/staging/prod).', 'Standards for deploying Rai-Tech applications to OpenShift (OCP). Deployment configuration: define resource requests and limits for all containers (CPU request: 100m, limit: 500m; Memory request: 128Mi, limit: 512Mi — adjust per workload). Liveness probe: use /health/live endpoint, initialDelaySeconds: 30, periodSeconds: 10. Readiness probe: use /health/ready endpoint, initialDelaySeconds: 15, periodSeconds: 5. Config maps for non-sensitive configuration, Secrets for sensitive values. Network policies: deny all ingress by default, explicitly allow required traffic. Image pull policy: Always for latest-based tags, IfNotPresent for pinned versions. Use OpenShift Routes with TLS termination — never expose unencrypted HTTP externally. Namespace per environment (dev/staging/prod).', 40, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'DEV-04');

  -- TypeScript and React (prefix: TSR)
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_10, 'TSR-01', 'TypeScript Configuration Standards', 'All Rai-Tech TypeScript projects must use strict mode.', 'All Rai-Tech TypeScript projects must use strict mode.', 'All Rai-Tech TypeScript projects must use strict mode. tsconfig.json required settings: "strict": true (enables strictNullChecks, noImplicitAny, strictFunctionTypes etc), "noUncheckedIndexedAccess": true (array access returns T | undefined), "exactOptionalPropertyTypes": true (optional properties cannot be set to undefined explicitly), "noImplicitReturns": true, "noFallthroughCasesInSwitch": true. Never use @ts-ignore — use @ts-expect-error with a comment explaining why, and treat these as technical debt. Never use any — use unknown for values of unknown type and narrow before use. Use type imports: import type { Foo } from ''./foo'' for type-only imports (improves build performance). Prefer interface over type for object shapes (better error messages, supports declaration merging).', 'All Rai-Tech TypeScript projects must use strict mode. tsconfig.json required settings: "strict": true (enables strictNullChecks, noImplicitAny, strictFunctionTypes etc), "noUncheckedIndexedAccess": true (array access returns T | undefined), "exactOptionalPropertyTypes": true (optional properties cannot be set to undefined explicitly), "noImplicitReturns": true, "noFallthroughCasesInSwitch": true. Never use @ts-ignore — use @ts-expect-error with a comment explaining why, and treat these as technical debt. Never use any — use unknown for values of unknown type and narrow before use. Use type imports: import type { Foo } from ''./foo'' for type-only imports (improves build performance). Prefer interface over type for object shapes (better error messages, supports declaration merging).', 10, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'TSR-01');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_10, 'TSR-02', 'React Component Standards', 'React component conventions for Rai-Tech projects.', 'React component conventions for Rai-Tech projects.', 'React component conventions for Rai-Tech projects. Always use functional components with hooks — no class components in new code. Component naming: PascalCase, one component per file, filename matches component name. Props: define an explicit interface for all component props (no object spreading unknown props). Avoid prop drilling beyond 2 levels — use Context or state management. Keep components small and focused — if a component is > 200 lines it likely needs splitting. Co-locate: styles, tests, and types with the component file. Use React.memo() only when profiling shows unnecessary re-renders — not as a default. Keys: always use stable, unique keys in lists — never array index unless the list is static. Error boundaries: wrap all route-level components in an error boundary.', 'React component conventions for Rai-Tech projects. Always use functional components with hooks — no class components in new code. Component naming: PascalCase, one component per file, filename matches component name. Props: define an explicit interface for all component props (no object spreading unknown props). Avoid prop drilling beyond 2 levels — use Context or state management. Keep components small and focused — if a component is > 200 lines it likely needs splitting. Co-locate: styles, tests, and types with the component file. Use React.memo() only when profiling shows unnecessary re-renders — not as a default. Keys: always use stable, unique keys in lists — never array index unless the list is static. Error boundaries: wrap all route-level components in an error boundary.', 20, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'TSR-02');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_10, 'TSR-03', 'State Management', 'State management philosophy: use the simplest solution that works.', 'State management philosophy: use the simplest solution that works.', 'State management philosophy: use the simplest solution that works. Local component state (useState): for UI state that doesn''t need to be shared. Context + useReducer: for shared state within a feature — not global state. TanStack Query (React Query): for all server state (API data) — handles caching, refetching, loading/error states, and eliminates most useEffect-for-data-fetching patterns. Zustand: for global client state that must persist across routes (user preferences, UI state). Never use Redux in new projects — it''s too much ceremony for the value it provides. Supabase Realtime: subscribe to database changes directly in components using the Supabase JS client — pair with TanStack Query for initial load and Realtime for updates.', 'State management philosophy: use the simplest solution that works. Local component state (useState): for UI state that doesn''t need to be shared. Context + useReducer: for shared state within a feature — not global state. TanStack Query (React Query): for all server state (API data) — handles caching, refetching, loading/error states, and eliminates most useEffect-for-data-fetching patterns. Zustand: for global client state that must persist across routes (user preferences, UI state). Never use Redux in new projects — it''s too much ceremony for the value it provides. Supabase Realtime: subscribe to database changes directly in components using the Supabase JS client — pair with TanStack Query for initial load and Realtime for updates.', 30, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'TSR-03');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_10, 'TSR-04', 'Supabase Client Patterns — TypeScript', 'TypeScript patterns for Supabase in React applications.', 'TypeScript patterns for Supabase in React applications.', 'TypeScript patterns for Supabase in React applications. Generate types: always use supabase gen types typescript to generate Database type definitions — never manually write Supabase table types. Typed client: const supabase = createClient<Database>(url, key). Error handling: always destructure { data, error } and check error before using data — never assume success. RLS in client code: write queries assuming RLS is enforced — do not add user ID filters in client code when RLS already handles it. Realtime subscriptions: clean up subscriptions in useEffect return function to prevent memory leaks. Auth state: use onAuthStateChange listener rather than polling — store session in context. Never store session tokens in localStorage — use the Supabase JS client''s built-in session management (uses localStorage by default but with its own security handling).', 'TypeScript patterns for Supabase in React applications. Generate types: always use supabase gen types typescript to generate Database type definitions — never manually write Supabase table types. Typed client: const supabase = createClient<Database>(url, key). Error handling: always destructure { data, error } and check error before using data — never assume success. RLS in client code: write queries assuming RLS is enforced — do not add user ID filters in client code when RLS already handles it. Realtime subscriptions: clean up subscriptions in useEffect return function to prevent memory leaks. Auth state: use onAuthStateChange listener rather than polling — store session in context. Never store session tokens in localStorage — use the Supabase JS client''s built-in session management (uses localStorage by default but with its own security handling).', 40, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'TSR-04');

  -- Python (prefix: PY)
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_11, 'PY-01', 'Python Project Standards', 'Python version: 3.11+ for all new projects.', 'Python version: 3.11+ for all new projects.', 'Python version: 3.11+ for all new projects. Package management: use uv (not pip or poetry) — it is significantly faster and provides lockfile support. Project structure: src layout (src/[package_name]/) to avoid import issues. Type hints: required for all public function signatures — use mypy in strict mode. Formatting: ruff for linting and formatting (replaces black + isort + flake8). Docstrings: Google style docstrings for all public modules, classes, and functions. Never use mutable default arguments (def f(x=[]) is a Python antipattern). Use pathlib.Path not os.path for all file system operations. Prefer dataclasses or Pydantic models over plain dicts for structured data. Environment variables: use python-dotenv locally, always read from environment in production.', 'Python version: 3.11+ for all new projects. Package management: use uv (not pip or poetry) — it is significantly faster and provides lockfile support. Project structure: src layout (src/[package_name]/) to avoid import issues. Type hints: required for all public function signatures — use mypy in strict mode. Formatting: ruff for linting and formatting (replaces black + isort + flake8). Docstrings: Google style docstrings for all public modules, classes, and functions. Never use mutable default arguments (def f(x=[]) is a Python antipattern). Use pathlib.Path not os.path for all file system operations. Prefer dataclasses or Pydantic models over plain dicts for structured data. Environment variables: use python-dotenv locally, always read from environment in production.', 10, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'PY-01');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_11, 'PY-02', 'LangGraph Agent Standards', 'Standards for LangGraph agentic workflows in Rai-Tech''s AI stack.', 'Standards for LangGraph agentic workflows in Rai-Tech''s AI stack.', 'Standards for LangGraph agentic workflows in Rai-Tech''s AI stack. State design: define a TypedDict for all graph state — never pass untyped dicts through the graph. Node design: each node is a pure function that takes state and returns a partial state update — no side effects except intentional tool calls. Edge conditions: use typed conditional edges with explicit return values — not string-based routing. Error handling: all tool calls must handle errors gracefully — return error information in state rather than raising exceptions. Checkpointing: enable LangGraph checkpointing for long-running workflows — use PostgreSQL checkpointer for production (not in-memory). Human-in-the-loop: use interrupt_before for any node that takes irreversible actions. Testing: test each node function independently before testing the full graph.', 'Standards for LangGraph agentic workflows in Rai-Tech''s AI stack. State design: define a TypedDict for all graph state — never pass untyped dicts through the graph. Node design: each node is a pure function that takes state and returns a partial state update — no side effects except intentional tool calls. Edge conditions: use typed conditional edges with explicit return values — not string-based routing. Error handling: all tool calls must handle errors gracefully — return error information in state rather than raising exceptions. Checkpointing: enable LangGraph checkpointing for long-running workflows — use PostgreSQL checkpointer for production (not in-memory). Human-in-the-loop: use interrupt_before for any node that takes irreversible actions. Testing: test each node function independently before testing the full graph.', 20, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'PY-02');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_11, 'PY-03', 'vLLM Integration Standards', 'Standards for calling Rai-Tech''s self-hosted vLLM (Nemotron) endpoints.', 'Standards for calling Rai-Tech''s self-hosted vLLM (Nemotron) endpoints.', 'Standards for calling Rai-Tech''s self-hosted vLLM (Nemotron) endpoints. Client: use the OpenAI-compatible API client (openai Python package with base_url pointing to vLLM). Never hardcode model names — read from environment variable (VLLM_MODEL_NAME). Always set explicit max_tokens — never rely on model default. Temperature: 0.0 for deterministic tasks (classification, extraction), 0.7-1.0 for creative generation. System prompts: store in version-controlled files not hardcoded strings. Retry logic: implement exponential backoff with jitter for transient failures — vLLM can return 429 or 503 under load. Timeout: set explicit request timeout (60s for normal, 300s for long generation). Log all inference calls with model name, input token count, output token count, and latency.', 'Standards for calling Rai-Tech''s self-hosted vLLM (Nemotron) endpoints. Client: use the OpenAI-compatible API client (openai Python package with base_url pointing to vLLM). Never hardcode model names — read from environment variable (VLLM_MODEL_NAME). Always set explicit max_tokens — never rely on model default. Temperature: 0.0 for deterministic tasks (classification, extraction), 0.7-1.0 for creative generation. System prompts: store in version-controlled files not hardcoded strings. Retry logic: implement exponential backoff with jitter for transient failures — vLLM can return 429 or 503 under load. Timeout: set explicit request timeout (60s for normal, 300s for long generation). Log all inference calls with model name, input token count, output token count, and latency.', 30, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'PY-03');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_11, 'PY-04', 'RAG Pipeline Standards', 'Standards for retrieval-augmented generation using pgvector.', 'Standards for retrieval-augmented generation using pgvector.', 'Standards for retrieval-augmented generation using pgvector. Chunking: chunk documents by semantic boundary (paragraph, section) not fixed character count — use a minimum of 256 tokens and maximum of 512 tokens per chunk, with 50-token overlap. Metadata: store source document ID, section title, page number, and creation date alongside each chunk. Embedding: batch embed chunks (do not embed one at a time) — use Nemotron embedding endpoint or OpenAI text-embedding-3-small. Retrieval: retrieve top-k=10 candidates, rerank using cross-encoder model to get top-3 for context. Hybrid search: combine pgvector cosine similarity with PostgreSQL full-text search — weight 0.6 vector + 0.4 BM25. Context assembly: include source metadata in context so LLM can cite sources. Never inject retrieved content without length limits — enforce max context window.', 'Standards for retrieval-augmented generation using pgvector. Chunking: chunk documents by semantic boundary (paragraph, section) not fixed character count — use a minimum of 256 tokens and maximum of 512 tokens per chunk, with 50-token overlap. Metadata: store source document ID, section title, page number, and creation date alongside each chunk. Embedding: batch embed chunks (do not embed one at a time) — use Nemotron embedding endpoint or OpenAI text-embedding-3-small. Retrieval: retrieve top-k=10 candidates, rerank using cross-encoder model to get top-3 for context. Hybrid search: combine pgvector cosine similarity with PostgreSQL full-text search — weight 0.6 vector + 0.4 BM25. Context assembly: include source metadata in context so LLM can cite sources. Never inject retrieved content without length limits — enforce max context window.', 40, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'PY-04');

  -- API Design (prefix: API)
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_12, 'API-01', 'REST API Conventions', 'Consistent REST API design across all Rai-Tech services.', 'Consistent REST API design across all Rai-Tech services.', 'Consistent REST API design across all Rai-Tech services. URLs: lowercase kebab-case (/patient-records not /PatientRecords), plural nouns for collections (/patients), nested resources for ownership (/patients/{id}/appointments), no verbs in URLs (/patients/{id}/discharge not /dischargePatient). Query parameters: use for filtering (status=active), sorting (sort=name&order=asc), pagination (page=1&limit=20 or cursor=xxx&limit=20), and field selection (fields=id,name,email). Request body: always JSON with Content-Type: application/json. Response envelope: return data directly for single resources, {data: [], meta: {total, page, limit}} for collections. Never return null for empty collections — return empty array. HATEOAS: not required but link headers for pagination are encouraged.', 'Consistent REST API design across all Rai-Tech services. URLs: lowercase kebab-case (/patient-records not /PatientRecords), plural nouns for collections (/patients), nested resources for ownership (/patients/{id}/appointments), no verbs in URLs (/patients/{id}/discharge not /dischargePatient). Query parameters: use for filtering (status=active), sorting (sort=name&order=asc), pagination (page=1&limit=20 or cursor=xxx&limit=20), and field selection (fields=id,name,email). Request body: always JSON with Content-Type: application/json. Response envelope: return data directly for single resources, {data: [], meta: {total, page, limit}} for collections. Never return null for empty collections — return empty array. HATEOAS: not required but link headers for pagination are encouraged.', 10, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'API-01');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_12, 'API-02', 'Supabase Edge Function Design', 'Design standards for Pronghorn and Rai-Tech Supabase edge functions.', 'Design standards for Pronghorn and Rai-Tech Supabase edge functions.', 'Design standards for Pronghorn and Rai-Tech Supabase edge functions. Every edge function must: handle CORS preflight (OPTIONS method returns 204 with appropriate headers), validate the Authorization header and create a user-scoped Supabase client, validate all input parameters with descriptive error messages, return structured JSON responses consistently. Error format: {error: string, code: string, details?: object}. Success format: {data: T, meta?: object}. Never use the service_role key in edge functions unless the operation explicitly requires bypassing RLS — use the user''s JWT to preserve RLS enforcement. Function naming: kebab-case matching the operation (create-project, sync-repository). Always set a function timeout — default is 60s, increase only if justified.', 'Design standards for Pronghorn and Rai-Tech Supabase edge functions. Every edge function must: handle CORS preflight (OPTIONS method returns 204 with appropriate headers), validate the Authorization header and create a user-scoped Supabase client, validate all input parameters with descriptive error messages, return structured JSON responses consistently. Error format: {error: string, code: string, details?: object}. Success format: {data: T, meta?: object}. Never use the service_role key in edge functions unless the operation explicitly requires bypassing RLS — use the user''s JWT to preserve RLS enforcement. Function naming: kebab-case matching the operation (create-project, sync-repository). Always set a function timeout — default is 60s, increase only if justified.', 20, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'API-02');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_12, 'API-03', 'API Versioning Strategy', 'All Rai-Tech APIs must be versioned to allow backward-compatible evolution.', 'All Rai-Tech APIs must be versioned to allow backward-compatible evolution.', 'All Rai-Tech APIs must be versioned to allow backward-compatible evolution. URL path versioning: /api/v1/, /api/v2/ — simplest to implement and cache, preferred for public APIs. Header versioning: Accept: application/vnd.boost.v2+json — preferred for internal service-to-service APIs. Rules: never make breaking changes in the same version (breaking = removing a field, changing a field type, changing auth requirements), deprecate old versions with a Deprecation header and sunset date, maintain a minimum of two versions simultaneously, document all breaking changes in a changelog. For Supabase edge functions: include version in the function path (functions/v1/create-project).', 'All Rai-Tech APIs must be versioned to allow backward-compatible evolution. URL path versioning: /api/v1/, /api/v2/ — simplest to implement and cache, preferred for public APIs. Header versioning: Accept: application/vnd.boost.v2+json — preferred for internal service-to-service APIs. Rules: never make breaking changes in the same version (breaking = removing a field, changing a field type, changing auth requirements), deprecate old versions with a Deprecation header and sunset date, maintain a minimum of two versions simultaneously, document all breaking changes in a changelog. For Supabase edge functions: include version in the function path (functions/v1/create-project).', 30, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'API-03');

  -- AI and ML (prefix: AI)
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_13, 'AI-01', 'Prompt Engineering Standards', 'Standards for writing and managing prompts in Rai-Tech AI systems.', 'Standards for writing and managing prompts in Rai-Tech AI systems.', 'Standards for writing and managing prompts in Rai-Tech AI systems. System prompts: always use a system prompt to set context and constraints — never rely on user prompt alone. Structure: role → context → constraints → output format → examples. Store prompts in version-controlled files (not hardcoded strings or database blobs) — prompts are code. Prompt versioning: include version in prompt file name, log which prompt version was used for each inference. Output format: always specify the desired output format explicitly (JSON schema, markdown structure etc) — do not leave format to the model''s discretion for structured data. Constraints: explicitly state what the model should NOT do — negative constraints are as important as positive ones. Test prompts: write evaluation sets with expected outputs — test prompt changes against the eval set before deploying.', 'Standards for writing and managing prompts in Rai-Tech AI systems. System prompts: always use a system prompt to set context and constraints — never rely on user prompt alone. Structure: role → context → constraints → output format → examples. Store prompts in version-controlled files (not hardcoded strings or database blobs) — prompts are code. Prompt versioning: include version in prompt file name, log which prompt version was used for each inference. Output format: always specify the desired output format explicitly (JSON schema, markdown structure etc) — do not leave format to the model''s discretion for structured data. Constraints: explicitly state what the model should NOT do — negative constraints are as important as positive ones. Test prompts: write evaluation sets with expected outputs — test prompt changes against the eval set before deploying.', 10, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'AI-01');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_13, 'AI-02', 'AI Output Validation', 'Never trust raw LLM output in production data flows without validation.', 'Never trust raw LLM output in production data flows without validation.', 'Never trust raw LLM output in production data flows without validation. Structured output: use JSON mode or structured output features when available — fall back to regex extraction with validation. Schema validation: validate all LLM-generated JSON against a Pydantic model or JSON Schema before use. Hallucination defence: for factual outputs, require the model to cite retrieved sources — do not use model knowledge alone for health information. Guardrails: implement input and output guardrails for patient-facing applications — check for PII in prompts before sending to external APIs, check output for appropriate clinical content. Human review: any AI-generated content used in clinical decisions must have a human review step — never fully automate clinical recommendations. Logging: log all AI inference inputs and outputs for audit purposes in healthcare applications.', 'Never trust raw LLM output in production data flows without validation. Structured output: use JSON mode or structured output features when available — fall back to regex extraction with validation. Schema validation: validate all LLM-generated JSON against a Pydantic model or JSON Schema before use. Hallucination defence: for factual outputs, require the model to cite retrieved sources — do not use model knowledge alone for health information. Guardrails: implement input and output guardrails for patient-facing applications — check for PII in prompts before sending to external APIs, check output for appropriate clinical content. Human review: any AI-generated content used in clinical decisions must have a human review step — never fully automate clinical recommendations. Logging: log all AI inference inputs and outputs for audit purposes in healthcare applications.', 20, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'AI-02');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_13, 'AI-03', 'Responsible AI and Privacy', 'Responsible AI requirements for Rai-Tech AI applications.', 'Responsible AI requirements for Rai-Tech AI applications.', 'Responsible AI requirements for Rai-Tech AI applications. Data minimisation: send only the minimum data required to the AI model — do not send full patient records when a summary suffices. External API restrictions: do not send personally identifiable health information to external AI APIs (OpenAI, Anthropic, Google) — use self-hosted Nemotron via vLLM for all health-related AI processing. Bias assessment: for any AI model used in clinical or administrative decisions, document the training data source, assess for demographic bias, and monitor outputs over time. Explainability: for AI-assisted decisions, be able to explain to a patient why a recommendation was made — pure black-box decisions are not acceptable in healthcare contexts. Model cards: maintain a model card for all custom-trained models (DistilBERT ticket router etc) documenting purpose, training data, limitations, and known failure modes.', 'Responsible AI requirements for Rai-Tech AI applications. Data minimisation: send only the minimum data required to the AI model — do not send full patient records when a summary suffices. External API restrictions: do not send personally identifiable health information to external AI APIs (OpenAI, Anthropic, Google) — use self-hosted Nemotron via vLLM for all health-related AI processing. Bias assessment: for any AI model used in clinical or administrative decisions, document the training data source, assess for demographic bias, and monitor outputs over time. Explainability: for AI-assisted decisions, be able to explain to a patient why a recommendation was made — pure black-box decisions are not acceptable in healthcare contexts. Model cards: maintain a model card for all custom-trained models (DistilBERT ticket router etc) documenting purpose, training data, limitations, and known failure modes.', 30, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'AI-03');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_13, 'AI-04', 'DistilBERT and Custom Model Standards', 'Standards for Rai-Tech''s custom ML models including the DistilBERT healthcare IT ticket router.', 'Standards for Rai-Tech''s custom ML models including the DistilBERT healthcare IT ticket router.', 'Standards for Rai-Tech''s custom ML models including the DistilBERT healthcare IT ticket router. Model versioning: use MLflow or DVC for experiment tracking and model versioning — every deployed model must have a tracked version. Training data: version-control training datasets, document data sources and collection dates, maintain a held-out test set never used during training. Evaluation: report precision, recall, F1, and confusion matrix per class — not just accuracy. Accuracy of 90-95% on 700k tickets is the current benchmark — any new version must exceed this before deployment. Serving: deploy via vLLM for transformer models, or dedicated FastAPI service for simpler models. Monitoring: track prediction distribution drift — alert if output class distribution changes significantly from training distribution. Retraining: establish a cadence for retraining when data drift is detected.', 'Standards for Rai-Tech''s custom ML models including the DistilBERT healthcare IT ticket router. Model versioning: use MLflow or DVC for experiment tracking and model versioning — every deployed model must have a tracked version. Training data: version-control training datasets, document data sources and collection dates, maintain a held-out test set never used during training. Evaluation: report precision, recall, F1, and confusion matrix per class — not just accuracy. Accuracy of 90-95% on 700k tickets is the current benchmark — any new version must exceed this before deployment. Serving: deploy via vLLM for transformer models, or dedicated FastAPI service for simpler models. Monitoring: track prediction distribution drift — alert if output class distribution changes significantly from training distribution. Retraining: establish a cadence for retraining when data drift is detected.', 40, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'AI-04');

  -- Supabase (prefix: SUP)
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_14, 'SUP-01', 'Local Development with Supabase CLI', 'All Rai-Tech developers using Supabase must use the Supabase CLI for local development — never develop directly against production or staging Supabase projects.', 'All Rai-Tech developers using Supabase must use the Supabase CLI for local development — never develop directly against production or staging Supabase projects.', 'All Rai-Tech developers using Supabase must use the Supabase CLI for local development — never develop directly against production or staging Supabase projects. Setup: npm install supabase --save-dev (use project-local CLI, not global install), supabase start (starts full local stack via Docker). Required in every project: supabase/config.toml (committed), supabase/migrations/ (all committed), .env.local for local keys (gitignored). Local URLs: API at http://127.0.0.1:54321, Studio at http://127.0.0.1:54323, DB at postgresql://postgres:postgres@127.0.0.1:54322/postgres. After supabase start: always run supabase db push to apply any pending migrations. Keys: get local anon and service_role keys from supabase status — the local keys are non-secret (shared defaults) but never use them in production.', 'All Rai-Tech developers using Supabase must use the Supabase CLI for local development — never develop directly against production or staging Supabase projects. Setup: npm install supabase --save-dev (use project-local CLI, not global install), supabase start (starts full local stack via Docker). Required in every project: supabase/config.toml (committed), supabase/migrations/ (all committed), .env.local for local keys (gitignored). Local URLs: API at http://127.0.0.1:54321, Studio at http://127.0.0.1:54323, DB at postgresql://postgres:postgres@127.0.0.1:54322/postgres. After supabase start: always run supabase db push to apply any pending migrations. Keys: get local anon and service_role keys from supabase status — the local keys are non-secret (shared defaults) but never use them in production.', 10, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'SUP-01');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_14, 'SUP-02', 'Supabase Auth Configuration', 'Auth configuration standards for Supabase projects.', 'Auth configuration standards for Supabase projects.', 'Auth configuration standards for Supabase projects. Email auth: enable email confirmation in production — disable only in development. Password requirements: minimum 8 characters (set in Supabase Auth settings). JWT expiry: access token 1 hour, refresh token 7 days for most apps, shorter for healthcare apps. Redirect URLs: whitelist only your specific app URLs — never use wildcard (*) in production. Custom SMTP: always configure a custom SMTP provider in production — never rely on Supabase''s built-in email service (rate limited, not SLA-backed). Azure AD SSO: configure via SAML 2.0 or OIDC provider in Supabase Auth settings. User metadata: store application-specific user data in a profiles table linked to auth.users — do not rely solely on Supabase user metadata. Admin operations: always use the Supabase Admin API (service_role) from server-side code, never client-side.', 'Auth configuration standards for Supabase projects. Email auth: enable email confirmation in production — disable only in development. Password requirements: minimum 8 characters (set in Supabase Auth settings). JWT expiry: access token 1 hour, refresh token 7 days for most apps, shorter for healthcare apps. Redirect URLs: whitelist only your specific app URLs — never use wildcard (*) in production. Custom SMTP: always configure a custom SMTP provider in production — never rely on Supabase''s built-in email service (rate limited, not SLA-backed). Azure AD SSO: configure via SAML 2.0 or OIDC provider in Supabase Auth settings. User metadata: store application-specific user data in a profiles table linked to auth.users — do not rely solely on Supabase user metadata. Admin operations: always use the Supabase Admin API (service_role) from server-side code, never client-side.', 20, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'SUP-02');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_14, 'SUP-03', 'Supabase Storage Standards', 'Standards for Supabase Storage (S3-compatible).', 'Standards for Supabase Storage (S3-compatible).', 'Standards for Supabase Storage (S3-compatible). Bucket creation: always create buckets with RLS enabled (public = false) unless explicitly serving public assets. Bucket naming: lowercase-kebab-case, descriptive (patient-documents, profile-avatars). Access: use signed URLs for private files (generate server-side with appropriate expiry — 1 hour for downloads, 15 minutes for uploads). Never expose storage service_role key to clients. File validation: validate file type and size server-side before allowing upload — use edge functions to gate uploads. File naming: use random UUIDs for filenames — never use user-supplied filenames (path traversal risk). Backups: Supabase Storage is backed by S3 — enable versioning for buckets containing important documents. Health information files: store only in Canada-region instances and document the storage location for PHIA compliance.', 'Standards for Supabase Storage (S3-compatible). Bucket creation: always create buckets with RLS enabled (public = false) unless explicitly serving public assets. Bucket naming: lowercase-kebab-case, descriptive (patient-documents, profile-avatars). Access: use signed URLs for private files (generate server-side with appropriate expiry — 1 hour for downloads, 15 minutes for uploads). Never expose storage service_role key to clients. File validation: validate file type and size server-side before allowing upload — use edge functions to gate uploads. File naming: use random UUIDs for filenames — never use user-supplied filenames (path traversal risk). Backups: Supabase Storage is backed by S3 — enable versioning for buckets containing important documents. Health information files: store only in Canada-region instances and document the storage location for PHIA compliance.', 30, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'SUP-03');
  INSERT INTO standards (id, category_id, code, title, description, short_description, long_description, content, order_index, is_system, created_by)
  SELECT gen_random_uuid(), v_cat_14, 'SUP-04', 'Supabase Realtime Standards', 'Standards for Supabase Realtime subscriptions.', 'Standards for Supabase Realtime subscriptions.', 'Standards for Supabase Realtime subscriptions. Enable selectively: only add tables to the Realtime publication that need live sync — every additional table adds overhead. SQL: ALTER PUBLICATION supabase_realtime ADD TABLE [table_name] — run once per table. Subscription patterns: use postgres_changes for database-driven updates (INSERT/UPDATE/DELETE events), use broadcast for ephemeral messaging (presence, cursor positions) that does not need to be stored. RLS with Realtime: Realtime respects RLS for postgres_changes — users only receive events for rows their RLS policies allow them to SELECT. Cleanup: always unsubscribe from Realtime channels when the component unmounts or the subscription is no longer needed. Channel naming: use descriptive names with entity and ID (project:abc-123, user-presence:room-456).', 'Standards for Supabase Realtime subscriptions. Enable selectively: only add tables to the Realtime publication that need live sync — every additional table adds overhead. SQL: ALTER PUBLICATION supabase_realtime ADD TABLE [table_name] — run once per table. Subscription patterns: use postgres_changes for database-driven updates (INSERT/UPDATE/DELETE events), use broadcast for ephemeral messaging (presence, cursor positions) that does not need to be stored. RLS with Realtime: Realtime respects RLS for postgres_changes — users only receive events for rows their RLS policies allow them to SELECT. Cleanup: always unsubscribe from Realtime channels when the component unmounts or the subscription is no longer needed. Channel naming: use descriptive names with entity and ID (project:abc-123, user-presence:room-456).', 40, false, v_user_id
  WHERE NOT EXISTS (SELECT 1 FROM standards WHERE code = 'SUP-04');

  RAISE NOTICE '=== Rai-Tech Standards Seed Complete: 15 categories, 72 standards ===';
END $$;

-- ── VERIFY ───────────────────────────────────────────────────────
SELECT sc.name AS category, sc.icon, sc.color, COUNT(s.id) AS standards
FROM standard_categories sc
LEFT JOIN standards s ON s.category_id = sc.id
GROUP BY sc.id, sc.name, sc.icon, sc.color, sc.order_index
ORDER BY sc.order_index;
